class TransportHighServerTCPManager:
    """
    Observes nonstandard high-port TCP services and actually catches them
    without assuming the larger port is the server.

    Public API:
        handle(pkt, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool
    """

    FLOW_TTL_SEC = 15 * 60
    FLOW_SOFT_MAX = 50_000
    RL_INTERVAL_SEC = 1.0

    # treat these as "high server" candidates
    MIN_SERVER_PORT = 1024

    # do not require modern 49152+ only; many real clients use lower ephemeral ranges
    MIN_CLIENT_PORT = 1024

    # small per-direction rolling buffer for cheap protocol peeks
    BUF_CAP = 2048

    # if we still cannot identify the app, emit generic high-port app-data after a short delay
    FALLBACK_EMIT_AFTER = 0.35

    _HTTP_METHODS = (
        b"GET ", b"POST ", b"PUT ", b"HEAD ", b"DELETE ",
        b"OPTIONS ", b"PATCH ", b"CONNECT ", b"TRACE "
    )
    _TLS_VERSIONS = {0x0301, 0x0302, 0x0303, 0x0304}

    def __init__(self, router_logger):
        self.log = router_logger
        self._flows = {}  # canonical_key -> state
        self._last_gc = time.time()
        self.log.log_message("[Transport][🧵 TCP][📦 HighServer] Manager ready.")

    def handle(self, pkt, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool:
        try:
            if TCP is None or not pkt or not pkt.haslayer(TCP):
                return False

            sport = int(sport)
            dport = int(dport)

            # must be a likely high-port service flow candidate
            if not self._is_high_server_candidate(sport, dport):
                return False

            now = time.time()
            key = self._flow_key(src_ip, sport, dst_ip, dport)
            st = self._flows.get(key)
            if st is None:
                st = self._new_flow(src_ip, sport, dst_ip, dport, now)
                self._flows[key] = st
            else:
                st["last_seen"] = now

            self._learn_roles(st, pkt, src_ip, sport, dst_ip, dport)

            data = self._payload(pkt)
            if data:
                direction = self._direction(st, src_ip, sport, dst_ip, dport)
                if direction == "c2s":
                    self._append(st["buf_c2s"], data)
                else:
                    self._append(st["buf_s2c"], data)

                st["bytes"] += len(data)
                st["pkts"] += 1
                if st["first_payload_ts"] is None:
                    st["first_payload_ts"] = now

            if not st["emitted"]:
                label, extra = self._classify(st)
                if label:
                    self._emit(st, label, extra, inbound_iface)
                    st["label"] = label
                    st["extra"] = extra
                    st["emitted"] = True
                elif st["first_payload_ts"] is not None and (now - st["first_payload_ts"]) >= self.FALLBACK_EMIT_AFTER:
                    role = self._server_endpoint_str(st)
                    self._emit(st, "App-Data", f"high-port service on {role}", inbound_iface)
                    st["label"] = "App-Data"
                    st["extra"] = f"high-port service on {role}"
                    st["emitted"] = True

            self._maybe_gc(now)
            return True

        except Exception:
            return False

    # ------------------------------------------------------------------
    # Flow + role logic
    # ------------------------------------------------------------------

    def _new_flow(self, src_ip, sport, dst_ip, dport, now):
        return {
            "created": now,
            "last_seen": now,
            "last_log": 0.0,
            "pkts": 0,
            "bytes": 0,
            "buf_c2s": bytearray(),
            "buf_s2c": bytearray(),
            "first_payload_ts": None,
            "emitted": False,
            "label": None,
            "extra": None,

            # learned roles
            "client": None,   # (ip, port)
            "server": None,   # (ip, port)

            # endpoint memory
            "ep_a": (str(src_ip), int(sport)),
            "ep_b": (str(dst_ip), int(dport)),
        }

    def _flow_key(self, src_ip, sport, dst_ip, dport):
        a = (str(src_ip), int(sport))
        b = (str(dst_ip), int(dport))
        return (a, b) if a <= b else (b, a)

    def _learn_roles(self, st, pkt, src_ip, sport, dst_ip, dport):
        src_ep = (str(src_ip), int(sport))
        dst_ep = (str(dst_ip), int(dport))

        if st["client"] is not None and st["server"] is not None:
            return

        flags = self._tcp_flags_string(pkt)

        # SYN without ACK is the best signal for initiator/client
        if "S" in flags and "A" not in flags:
            st["client"] = src_ep
            st["server"] = dst_ep
            return

        # if one side is clearly low and the other high, low side is usually client
        if self._looks_client_port(sport) and self._looks_server_port(dport):
            st["client"] = src_ep
            st["server"] = dst_ep
            return
        if self._looks_client_port(dport) and self._looks_server_port(sport):
            st["client"] = dst_ep
            st["server"] = src_ep
            return

        # otherwise prefer the side whose payload looks like a request
        data = self._payload(pkt)
        if data:
            if self._looks_requestish(data):
                st["client"] = src_ep
                st["server"] = dst_ep
                return
            if self._looks_responseish(data):
                st["client"] = dst_ep
                st["server"] = src_ep
                return

        # final fallback: lower port is more likely server
        if sport < dport:
            st["server"] = src_ep
            st["client"] = dst_ep
        elif dport < sport:
            st["server"] = dst_ep
            st["client"] = src_ep
        else:
            st["client"] = src_ep
            st["server"] = dst_ep

    def _direction(self, st, src_ip, sport, dst_ip, dport):
        src_ep = (str(src_ip), int(sport))
        dst_ep = (str(dst_ip), int(dport))

        if st["client"] is not None and src_ep == st["client"]:
            return "c2s"
        if st["server"] is not None and src_ep == st["server"]:
            return "s2c"

        # fallback if roles somehow missing
        if self._looks_request_side(src_ep, dst_ep):
            return "c2s"
        return "s2c"

    def _looks_client_port(self, port: int) -> bool:
        return int(port) >= self.MIN_CLIENT_PORT

    def _looks_server_port(self, port: int) -> bool:
        return int(port) >= self.MIN_SERVER_PORT

    def _is_high_server_candidate(self, sport: int, dport: int) -> bool:
        sport = int(sport)
        dport = int(dport)

        # both must be non-well-known/highish
        if sport < self.MIN_SERVER_PORT and dport < self.MIN_SERVER_PORT:
            return False

        # reject exact equality noise
        if sport == dport:
            return False

        return True

    def _looks_request_side(self, src_ep, dst_ep) -> bool:
        # higher port is often client, but this is only a weak fallback
        return int(src_ep[1]) >= int(dst_ep[1])

    # ------------------------------------------------------------------
    # Classification
    # ------------------------------------------------------------------

    def _classify(self, st):
        c2s = bytes(st["buf_c2s"])
        s2c = bytes(st["buf_s2c"])

        # HTTP
        if self._looks_http_request(c2s):
            host = self._extract_http_host(c2s)
            path = self._extract_http_path(c2s)
            extra = f"HTTP request path={path}"
            if host:
                extra += f" host={host}"
            return "HTTP", extra

        if self._looks_http_response(s2c):
            code = self._extract_http_status(s2c)
            return "HTTP", f"HTTP response status={code or '-'}"

        # TLS
        if self._looks_tls_clienthello(c2s):
            sni = self._extract_sni(c2s)
            return "TLS", f"ClientHello sni={sni}" if sni else "ClientHello"

        if self._looks_tls_record(s2c):
            return "TLS", "TLS server record"

        # SSH
        if c2s.startswith(b"SSH-") or s2c.startswith(b"SSH-"):
            banner = self._safe_ascii(c2s if c2s.startswith(b"SSH-") else s2c, 120)
            return "SSH", banner or "banner"

        # FTP control
        ftp_hint = self._ftp_hint(c2s) or self._ftp_hint(s2c)
        if ftp_hint:
            return "FTP", ftp_hint

        # RDP
        if self._looks_rdp(c2s) or self._looks_rdp(s2c):
            return "RDP", "x224/tpkt or mstshash"

        return None, None

    def _looks_http_request(self, buf: bytes) -> bool:
        if not buf:
            return False
        head = buf[:16]
        return any(head.startswith(m) for m in self._HTTP_METHODS)

    def _looks_http_response(self, buf: bytes) -> bool:
        return bool(buf.startswith(b"HTTP/1."))

    def _looks_tls_record(self, buf: bytes) -> bool:
        if len(buf) < 5:
            return False
        if buf[0] not in (0x14, 0x15, 0x16, 0x17):
            return False
        ver = (buf[1] << 8) | buf[2]
        return ver in self._TLS_VERSIONS

    def _looks_tls_clienthello(self, buf: bytes) -> bool:
        if not self._looks_tls_record(buf):
            return False
        if len(buf) < 6:
            return False
        return buf[0] == 0x16 and buf[5:6] == b"\x01"

    def _looks_rdp(self, buf: bytes) -> bool:
        if not buf:
            return False
        if len(buf) >= 4 and buf[0] == 0x03 and buf[1] == 0x00:
            return True
        if b"Cookie: mstshash=" in buf[:512]:
            return True
        return False

    def _looks_requestish(self, data: bytes) -> bool:
        head = data[:32]
        if any(head.startswith(m) for m in self._HTTP_METHODS):
            return True
        if head.startswith(b"SSH-"):
            return True
        if head.startswith((b"USER ", b"PASS ", b"RETR ", b"STOR ", b"LIST", b"PWD", b"CWD ")):
            return True
        if self._looks_tls_clienthello(data):
            return True
        return False

    def _looks_responseish(self, data: bytes) -> bool:
        head = data[:32]
        if head.startswith(b"HTTP/1."):
            return True
        if head.startswith((b"220 ", b"221 ", b"230 ", b"331 ", b"530 ")):
            return True
        if self._looks_tls_record(data) and not self._looks_tls_clienthello(data):
            return True
        return False

    # ------------------------------------------------------------------
    # Small extractors
    # ------------------------------------------------------------------

    def _extract_http_host(self, buf: bytes):
        try:
            for line in buf[:1024].split(b"\r\n"):
                if line.lower().startswith(b"host:"):
                    return self._safe_ascii(line.split(b":", 1)[1].strip(), 120)
        except Exception:
            pass
        return None

    def _extract_http_path(self, buf: bytes):
        try:
            line = buf.split(b"\r\n", 1)[0]
            parts = line.split(b" ")
            if len(parts) >= 2:
                return self._safe_ascii(parts[1], 180) or "/"
        except Exception:
            pass
        return "/"

    def _extract_http_status(self, buf: bytes):
        try:
            line = buf.split(b"\r\n", 1)[0]
            parts = line.split(b" ")
            if len(parts) >= 2:
                return self._safe_ascii(parts[1], 8)
        except Exception:
            pass
        return None

    def _extract_sni(self, buf: bytes):
        # cheap best-effort SNI scan, not full TLS parsing
        try:
            blob = bytes(buf[:1024])
            for i in range(0, max(0, len(blob) - 5)):
                ln = int.from_bytes(blob[i:i+2], "big", signed=False)
                if 3 <= ln <= 253 and i + 2 + ln <= len(blob):
                    cand = blob[i+2:i+2+ln]
                    if b"." in cand and all(32 <= b <= 126 for b in cand):
                        s = cand.decode("ascii", "ignore")
                        if "." in s and " " not in s and "/" not in s:
                            return s[:160]
        except Exception:
            pass
        return None

    def _ftp_hint(self, buf: bytes):
        if not buf:
            return None
        head = buf[:256]
        for token in (b"USER ", b"PASS ", b"RETR ", b"STOR ", b"LIST", b"PASV", b"PORT ", b"PWD", b"CWD "):
            if head.startswith(token):
                return token.decode("ascii", "ignore").strip()
        for code in (b"220 ", b"221 ", b"230 ", b"331 ", b"530 "):
            if head.startswith(code):
                return code.decode("ascii", "ignore").strip()
        return None

    # ------------------------------------------------------------------
    # Logging / utils
    # ------------------------------------------------------------------

    def _emit(self, st, label, extra, inbound_iface):
        now = time.time()
        if (now - float(st.get("last_log", 0.0) or 0.0)) < self.RL_INTERVAL_SEC:
            return
        st["last_log"] = now

        client = st["client"] or st["ep_a"]
        server = st["server"] or st["ep_b"]
        iface = self._iface_suffix(inbound_iface)

        msg = (
            f"[Transport][🧵 TCP][📦 HighServer] "
            f"{client[0]}:{client[1]} -> {server[0]}:{server[1]} "
            f"on {iface} | {label}"
        )
        if extra:
            msg += f" | {extra}"

        try:
            self.log.log_message(msg)
        except Exception:
            pass

    def _server_endpoint_str(self, st):
        server = st["server"]
        if not server:
            return "unknown-high-port"
        return f"{server[0]}:{server[1]}"

    def _payload(self, pkt):
        try:
            if Raw is not None and pkt.haslayer(Raw):
                raw = bytes(pkt[Raw].load or b"")
                if raw:
                    return raw
        except Exception:
            pass
        try:
            tcp = pkt[TCP]
            payload = bytes(tcp.payload or b"")
            return payload or b""
        except Exception:
            return b""

    def _append(self, buf: bytearray, data: bytes):
        if not data:
            return
        buf += data
        if len(buf) > self.BUF_CAP:
            del buf[: len(buf) - self.BUF_CAP]

    def _tcp_flags_string(self, pkt):
        try:
            return pkt[TCP].sprintf("%TCP.flags%")
        except Exception:
            return ""

    def _iface_suffix(self, inbound_iface):
        try:
            return inbound_iface.split("_")[-1] if inbound_iface else "-"
        except Exception:
            return inbound_iface or "-"

    def _safe_ascii(self, b, maxlen=128):
        try:
            if not b:
                return None
            s = b.decode("latin-1", "ignore") if isinstance(b, (bytes, bytearray)) else str(b)
            s = "".join(ch for ch in s if ch >= " " or ch == "\t")
            if len(s) > maxlen:
                s = s[:maxlen] + "…"
            return s
        except Exception:
            return None

    def _maybe_gc(self, now):
        if (now - self._last_gc) < 60:
            return

        stale = []
        for k, v in self._flows.items():
            if (now - float(v.get("last_seen", now))) > self.FLOW_TTL_SEC:
                stale.append(k)

        for k in stale:
            self._flows.pop(k, None)

        if len(self._flows) > self.FLOW_SOFT_MAX:
            victims = sorted(
                self._flows.items(),
                key=lambda kv: float(kv[1].get("last_seen", 0.0))
            )[: len(self._flows) - self.FLOW_SOFT_MAX]
            for k, _ in victims:
                self._flows.pop(k, None)

        self._last_gc = now
class TransportRIPManager:
    """
    Handles Routing Information Protocol:
      - RIP v1/v2 over IPv4 on UDP/520
      - RIPng over IPv6 on UDP/521

    Advanced observer features:
      • RIPv2 authentication RTE detection (simple password / MD5 trailer hint)
      • RIPv2 Next-Hop RTE handling (AFI=0, special entry) applied to subsequent entries
      • RIPng Next-Hop RTE handling (metric=0xFF) applied to subsequent entries
      • Classful + “smart guess” mask inference for RIP v1 (private/link-local/loopback/mcast)
      • Mask normalization for RIPv2 (force contiguous; derive /length)
      • Duplicate/TTL de-dupe and hysteresis-y change detection
      • ECMP hinting: same dst/prefix, same metric, different next-hops
      • Per-(sender, flow) cooldown + per-route TTL de-dupe
      • Per-sender lightweight counters + snapshot_metrics()
      • Inbound iface suffix included in every log
    """

    LOG_COOLDOWN = 640   # per (sip,sport,dip,dport,proto,cmd) cooldown
    ROUTE_TTL    = 30.0  # TTL de-dupe horizon
    HYSTERESIS_S = 2.5   # small quiet-time to damp fast flaps on a single route

    def __init__(self, router_logger, *, announce_ttl: float = ROUTE_TTL):
        import time as _t
        self.log = router_logger
        self._ttl = float(announce_ttl)
        self._t = _t

        # De-dupe caches
        # (sip,sport,dip,dport,route_key_full_tuple) -> ts
        self._last_seen: Dict[Tuple[str,int,str,int,str], float] = {}
        # (sip,sport,dip,dport,proto,cmd) -> not-before-ts
        self._cooldown_until: Dict[Tuple[str,int,str,int,str,int], float] = {}
        # (sip,sport,dip,dport,dst_key) -> last route state (metric, nh, tag, ver, ts)
        self._last_route_state: Dict[Tuple[str,int,str,int,str], Tuple[int, str, int, str, float]] = {}

        # Stats
        self._sender_stats: Dict[str, Dict[str, int]] = {}
        self._rate_last: Dict[str, float] = {}

        # Optional scapy dissectors (not required)
        try:
            from scapy.layers.rip import RIP, RIPng  # noqa: F401
            self._has_scapy = True
        except Exception:
            self._has_scapy = False

        self.log.log_message("[Transport][🛣️ RIP] Manager ready.")

    # ---------- Public entry ----------
    def handle(self, pkt, src_ip, dst_ip, sport, dport, inbound_iface=None):
        try:
            if dport == 520 or sport == 520:
                self._handle_rip_ipv4(pkt, src_ip, dst_ip, sport, dport, inbound_iface)
            elif dport == 521 or sport == 521:
                self._handle_ripng(pkt, src_ip, dst_ip, sport, dport, inbound_iface)
        except Exception as e:
            self._rate_log(f"[Transport][🛣️ RIP] parse error: {e}")

    # ---------- RIP v1/v2 (UDP/520 over IPv4) ----------
    def _handle_rip_ipv4(self, pkt, src_ip, dst_ip, sport, dport, inbound_iface):
        payload = self._raw(pkt)
        if len(payload) < 4:
            return
        cmd = payload[0]          # 1=request, 2=response
        ver = payload[1]          # 1=v1, 2=v2
        off = 4

        proto = f"RIPv{ver}"
        iface = self._iface_suffix(inbound_iface)

        # --- Auth RTE (RIPv2): AFI=0xFFFF at first entry
        auth_mode = None
        if ver == 2 and len(payload) >= off + 20:
            afi0 = int.from_bytes(payload[off:off+2], "big")
            if afi0 == 0xFFFF:
                auth_type = int.from_bytes(payload[off+2:off+4], "big")
                if auth_type == 2:
                    auth_mode = "simple"
                    self._rate_log(
                        f"[Transport][🛣️ {proto}] auth(simple) {src_ip}:{sport} → {dst_ip}:{dport} on {iface} (16B pwd hidden)"
                    )
                elif auth_type == 3:
                    auth_mode = "md5"
                    # Heuristic: MD5 trailer likely present if payload length > 24 + N*20
                    self._rate_log(
                        f"[Transport][🛣️ {proto}] auth(MD5) {src_ip}:{sport} → {dst_ip}:{dport} on {iface}"
                    )
                else:
                    auth_mode = f"type{auth_type}"
                    self._rate_log(
                        f"[Transport][🛣️ {proto}] auth({auth_mode}) {src_ip}:{sport} → {dst_ip}:{dport} on {iface}"
                    )
                off += 20  # consume auth RTE

        entries: List[Tuple[str, str, str, int, int]] = []
        nh_override = "-"  # Next-Hop RTE (RIPv2) applies to subsequent entries

        while off + 20 <= len(payload):
            e = payload[off:off+20]; off += 20
            afi = int.from_bytes(e[0:2], "big")

            # RIPv2 Next-Hop SPECIAL RTE (RFC 2453):
            # AFI=0, RouteTag=0, IP=0, Mask=0, NextHop=<ip>, Metric=0 (some impl. use 0xFFFF—tolerate)
            if ver == 2 and afi == 0:
                nh_bytes = e[12:16]
                metric_v = int.from_bytes(e[16:20], "big")
                ip_all_zero  = e[4:8]  == b"\x00\x00\x00\x00"
                msk_all_zero = e[8:12] == b"\x00\x00\x00\x00"
                if ip_all_zero and msk_all_zero:
                    nh = self.ip_str(nh_bytes)
                    if nh != "0.0.0.0":
                        nh_override = nh
                        self._rate_log(
                            f"[Transport][🛣️ {proto}] next-hop {nh} {src_ip}:{sport} → {dst_ip}:{dport} on {iface}"
                        )
                    continue
                # Otherwise it's some AFI=0 padding—skip
                continue

            if afi == 0xFFFF:
                # stray auth blocks mid-stream, ignore
                continue
            if afi == 0:
                # padding
                continue

            ip_bytes = e[4:8]
            ip       = self.ip_str(ip_bytes)
            metric   = int.from_bytes(e[16:20], "big")
            if not (1 <= metric <= 16):
                # Poisoned reverse seen as 16 is allowed; anything else drop
                if metric != 16:
                    continue

            if ver == 2:
                mask_bytes = e[8:12]
                nh_bytes   = e[12:16]
                tag        = int.from_bytes(e[2:4], "big")

                # Normalize mask (force contiguous) and prefer '-' for 0.0.0.0
                mask_norm, plen = self._normalize_mask(mask_bytes)
                mask = mask_norm if mask_norm != "0.0.0.0" else "-"
                # Apply Next-Hop override if present
                nh_raw = self.ip_str(nh_bytes)
                nexthop = nh_override if nh_override != "-" else (nh_raw if nh_raw != "0.0.0.0" else "-")

                # Clean up weird masks (non-contiguous compressed to contiguous)
                if mask != "-":
                    # When mask looks like /0, prefer '-' for logging clarity
                    if plen == 0:
                        mask = "-"
            else:
                # RIPv1
                mask = self._classful_mask_for(ip)
                tag = 0
                nexthop = nh_override if nh_override != "-" else "-"

            entries.append((ip, mask, nexthop, metric, tag))

        if entries:
            self._log_routes(src_ip, sport, dst_ip, dport, proto, cmd, entries, iface, auth_mode=auth_mode)

    # ---------- RIPng (UDP/521 over IPv6) ----------
    def _handle_ripng(self, pkt, src_ip, dst_ip, sport, dport, inbound_iface):
        payload = self._raw(pkt)
        if len(payload) < 4:
            return
        cmd = payload[0]      # 1=request, 2=response
        ver = payload[1]      # RIPng version is 1
        off = 4
        proto = "RIPng"
        iface = self._iface_suffix(inbound_iface)

        entries_fmt: List[Tuple[str, str, str, int, int]] = []
        curr_next_hop = "-"  # Next-Hop RTE applies to subsequent RTEs

        # RTE: IPv6 prefix(16) | RouteTag(2) | PrefixLen(1) | Metric(1)
        while off + 20 <= len(payload):
            e = payload[off:off+20]; off += 20
            metric = e[19]

            if metric == 0xFF:
                # Next Hop RTE per RFC 2080
                nh6 = self.inet6_str(e[0:16])
                curr_next_hop = nh6
                self._rate_log(
                    f"[Transport][🛣️ {proto}] next-hop {nh6} {src_ip}:{sport} → {dst_ip}:{dport} on {iface}"
                )
                continue

            if not (1 <= metric <= 16):
                if metric != 16:  # poisoned reverse ok; others skip
                    continue

            pfx = self.inet6_str(e[0:16])
            rtag = int.from_bytes(e[16:18], "big")
            plen = min(e[18], 128)
            entries_fmt.append((f"{pfx}/{plen}", "-", curr_next_hop, metric, rtag))

        if entries_fmt:
            self._log_routes(src_ip, sport, dst_ip, dport, proto, cmd, entries_fmt, iface)

    # ---------- Logging & change detection ----------
    def _log_routes(self, sip, sport, dip, dport, proto, cmd, entries, iface, *, auth_mode: str | None = None):
        now = self._t.time()
        shown = 0
        cmd_str = {1: "request", 2: "response"}.get(cmd, str(cmd))

        # per-flow cooldown guard
        cd_key = (sip, int(sport), dip, int(dport), str(proto), int(cmd))
        if now < self._cooldown_until.get(cd_key, 0.0):
            return

        # sender stats bucket
        sstat = self._sender_stats.setdefault(sip, {"ann": 0, "wdr": 0, "chg": 0, "tot": 0, "ecmp": 0})
        sstat["tot"] += 1

        # ECMP hinting prep: group by (dst, mask/prefix)
        ecmp_buckets: Dict[Tuple[str, str], Dict[str, int]] = {}

        for (dst, mask, nh, metric, tag) in entries:
            route_id = f"{dst}|{mask}|{proto}"
            de_dupe_key = (sip, int(sport), dip, int(dport), f"{route_id}|{nh}|{metric}|{tag}|{cmd}")
            last_ts = self._last_seen.get(de_dupe_key, 0.0)
            if now - last_ts < self._ttl:
                continue  # TTL de-dupe
            self._last_seen[de_dupe_key] = now

            # Change/withdraw detection keyed by route identity (dst/mask/proto)
            state_key = (sip, int(sport), dip, int(dport), route_id)
            prev = self._last_route_state.get(state_key)
            withdrew = (metric == 16)
            changed = False
            too_soon = False

            if prev:
                p_metric, p_nh, p_tag, p_ver, p_ts = prev
                if (p_metric != metric) or (p_nh != nh) or (p_tag != tag) or (p_ver != proto):
                    changed = True
                    # Apply small hysteresis to avoid chattiness
                    if now - p_ts < self.HYSTERESIS_S:
                        too_soon = True

            # Compose log line
            extra = [f"metric={metric}"]
            if mask not in ("-", "0.0.0.0"):
                extra.append(f"mask={mask}")
            if nh not in ("-", "0.0.0.0"):
                extra.append(f"nexthop={nh}")
            if tag:
                extra.append(f"tag={tag}")
            if auth_mode:
                extra.append(f"auth={auth_mode}")

            prefix = f"[Transport][🛣️ {proto}] {cmd_str} {sip}:{sport} → {dip}:{dport} on {iface} | {dst}"

            if withdrew:
                sstat["wdr"] += 1
                self._rate_log(f"{prefix} | WITHDRAW {' '.join(extra)}")
            elif prev is None:
                sstat["ann"] += 1
                self._rate_log(f"{prefix} | announce {' '.join(extra)}")
            elif changed and not too_soon:
                sstat["chg"] += 1
                self._rate_log(f"{prefix} | update {' '.join(extra)}")
            elif changed and too_soon:
                # silent (hysteresis), but still update snapshot below
                pass
            else:
                # No material change; still log minimally because TTL de-dupe passed
                self._rate_log(f"{prefix} | repeat {' '.join(extra)}")

            # Update last state snapshot
            self._last_route_state[state_key] = (metric, nh, tag, proto, now)
            shown += 1

            # ECMP bucket
            ecmp_key = (dst, mask)
            bucket = ecmp_buckets.setdefault(ecmp_key, {})
            if nh != "-":
                bucket_key = f"{metric}@{nh}"
                bucket[bucket_key] = bucket.get(bucket_key, 0) + 1

        # Emit ECMP hints (same dst/mask, same metric, >1 nexthop)
        for (dst, mask), combos in ecmp_buckets.items():
            metrics = {}
            for k in combos.keys():
                m = int(k.split("@", 1)[0])
                metrics.setdefault(m, 0)
                metrics[m] += 1
            for m, count in metrics.items():
                if count >= 2:
                    sstat["ecmp"] += 1
                    self._rate_log(f"[Transport][🛣️ {proto}] ECMP hint {dst} {mask} metric={m} via {count} nexthops")

        # flow cooldown
        if shown:
            self._cooldown_until[cd_key] = now + float(self.LOG_COOLDOWN)
            self._gc()

    # ---------- Metrics / GC ----------
    def snapshot_metrics(self) -> Dict[str, Any]:
        now = self._t.time()
        senders = {k: dict(v) for k, v in self._sender_stats.items()}
        return {
            "counters": {
                "unique_routes_cached": len(self._last_route_state),
                "dedupe_keys": len(self._last_seen),
                "cooldowns": len(self._cooldown_until),
                "senders": len(senders),
            },
            "senders": senders,
            "gc_hint": {
                "ttl": self._ttl,
                "log_cooldown": self.LOG_COOLDOWN,
                "now": now,
            },
        }

    def _gc(self):
        now = self._t.time()
        # expire per-route TTLs
        for k, ts in list(self._last_seen.items()):
            if now - ts > self._ttl:
                self._last_seen.pop(k, None)
        # trim cooldowns that are long past
        for k, t in list(self._cooldown_until.items()):
            if t < now - self.LOG_COOLDOWN:
                self._cooldown_until.pop(k, None)
        # trim stale last_route_state snapshots (2x TTL)
        for k, tup in list(self._last_route_state.items()):
            if now - tup[-1] > 2 * self._ttl:
                self._last_route_state.pop(k, None)

    # ---------- IO helpers ----------
    @staticmethod
    def _raw(pkt) -> bytes:
        try:
            from scapy.packet import Raw
            if pkt.haslayer(Raw):
                return bytes(pkt[Raw].load or b"")
        except Exception:
            pass
        try:
            return bytes(pkt.payload.payload.payload)
        except Exception:
            return b""

    def _rate_log(self, msg: str):
        try:
            self.log.log_message(msg)
        except Exception:
            pass

    @staticmethod
    def _iface_suffix(inbound_iface: str | None) -> str:
        try:
            if not inbound_iface:
                return "-"
            return inbound_iface.split("_")[-1]
        except Exception:
            return inbound_iface or "-"

    # ---------- tiny helpers ----------
    def ip_str(self, b4: bytes) -> str:
        try:
            import socket
            return socket.inet_ntop(socket.AF_INET, b4)
        except Exception:
            return ".".join(str(x) for x in b4)

    def inet6_str(self, b16: bytes) -> str:
        try:
            import socket
            return socket.inet_ntop(socket.AF_INET6, b16)
        except Exception:
            return ":".join(f"{(b16[i]<<8) | b16[i+1]:x}" for i in range(0,16,2))

    # ---------- Mask handling ----------
    @staticmethod
    def _mask_bytes_to_prefix(mask_bytes: bytes) -> int:
        """Return prefix length from mask (force contiguous by counting leading ones)."""
        v = int.from_bytes(mask_bytes, "big", signed=False)
        if v == 0:
            return 0
        # count leading ones until first zero
        inv = ~v & 0xFFFFFFFF
        # if non-contiguous, the following forces collapse to first zero boundary
        if (v | (v + 1)) & 0xFFFFFFFF != 0xFFFFFFFF:
            # non-contiguous: normalize by filling trailing ones -> contiguous
            while (v | (v + 1)) & 0xFFFFFFFF != 0xFFFFFFFF:
                v |= (v >> 1)
            v = (v ^ (v >> 1))  # ensure proper form; fallback: recompute from leading ones
        plen = 0
        for i in range(32):
            if (v & (1 << (31 - i))) != 0:
                plen += 1
            else:
                break
        return plen

    def _normalize_mask(self, mask_bytes: bytes) -> Tuple[str, int]:
        """Return (normalized dotted mask, prefix length) with contiguous bits."""
        plen = self._mask_bytes_to_prefix(mask_bytes)
        if plen <= 0:
            return "0.0.0.0", 0
        # build mask from prefix
        m = (0xFFFFFFFF << (32 - plen)) & 0xFFFFFFFF
        mb = m.to_bytes(4, "big")
        dotted = self.ip_str(mb)
        return dotted, plen

    # ---------- IPv4 classful + smart inference for RIP v1 ----------
    def _classful_mask_for(self, ip: str) -> str:
        """
        Prefer classful defaults but “smarten” for common special ranges:
          - Private: 10/8, 172.16/12, 192.168/16
          - Link-local: 169.254/16
          - Loopback: 127/8
          - Multicast/Reserved: 224/4 → no mask (“-”)
          - 0.0.0.0 default → “-”
        Otherwise fall back to classic A/B/C.
        """
        try:
            a, b, c, _ = (int(x) for x in ip.split(".", 3))
        except Exception:
            return "-"

        # Default / special cases
        if ip == "0.0.0.0":
            return "-"
        if 224 <= a <= 255:
            return "-"  # mcast/experimental/reserved
        if a == 127:
            return "255.0.0.0"  # loopback
        if a == 169 and b == 254:
            return "255.255.0.0"  # link-local
        if a == 10:
            return "255.0.0.0"  # 10/8
        if a == 172 and 16 <= b <= 31:
            return "255.240.0.0"  # 172.16/12 (best-effort “smart guess”)
        if a == 192 and b == 168:
            return "255.255.255.0"  # 192.168/16 typical /24

        # Classic classful fallback
        if 1 <= a <= 126:
            return "255.0.0.0"       # Class A
        if 128 <= a <= 191:
            return "255.255.0.0"     # Class B
        if 192 <= a <= 223:
            return "255.255.255.0"   # Class C
        return "-"
class TransportESPManager:
    """
    Observes IPsec over UDP (NAT-T) + IKEv2 + native ESP.

    Recognizes:
      • UDP/4500: NAT-T keepalive (single 0xFF)
      • UDP/4500: Non-ESP marker 0x00000000 + IKEv2 header
      • UDP/4500: ESP over NAT-T (no Non-ESP marker) -> {SPI, SEQ}
      • UDP/500 : IKEv2 header
      • IP proto 50 (ESP) on IPv4/IPv6 -> {SPI, SEQ}

    Public API
    ----------
    handle(packet, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool
    snapshot_metrics() -> dict
    clear_caches(kind: str | None = None) -> None
    set_budgets(bytes_budget: int | None = None, frames_budget: int | None = None) -> None
    set_hook(name: str, fn: Callable | None) -> None   # "ike", "esp", "anomaly", "summary"
    set_detect_non4500(enabled: bool) -> None          # observe ESP proto=50 outside 4500/500
    """

    NAT_T = 4500
    IKE   = 500

    # IKEv2 exchange type names (RFC 7296)
    IKE_X = {
        34: "IKE_SA_INIT",
        35: "IKE_AUTH",
        36: "CREATE_CHILD_SA",
        37: "INFORMATIONAL",
    }

    def __init__(self, router_logger, log_window: float = 2.0, detect_non4500: bool = True):
        self.log = router_logger
        self._last_log: Dict[str, float] = defaultdict(float)
        self._log_window = float(log_window)

        # lightweight counters
        # flow key: ((sip, sport),(dip, dport)) normalized + optional SPI
        self._esp_stats: Dict[Tuple[Tuple[Tuple[str,int],Tuple[str,int]], int], Dict[str, int]] = \
            defaultdict(lambda: {"pkts": 0, "bytes": 0})
        self._ike_stats: Dict[Tuple[str,int,str,int], Dict[str, int]] = \
            defaultdict(lambda: {"pkts": 0, "bytes": 0})

        # rekey detection per (peers,direction): remember last SPI set (rolling window)
        self._spi_recent: Dict[Tuple[Tuple[str,str], str], deque] = defaultdict(lambda: deque(maxlen=32))

        # summary cadence
        self._last_summary = time.time()
        self._summary_every = 60.0

        # budgets (soft)
        self._bytes_budget: Optional[int] = None
        self._frames_budget: Optional[int] = None
        self._bytes_seen = 0
        self._frames_seen = 0

        # hooks
        self._hooks: Dict[str, Optional[Callable[..., None]]] = {
            "ike": None, "esp": None, "anomaly": None, "summary": None
        }

        # enable observing native ESP (proto=50)
        self._detect_non4500 = bool(detect_non4500)

        self._safe_log("[Transport][🛡 ESP] Manager ready.")

    # ------------------- Public -------------------

    def set_budgets(self, bytes_budget: int | None = None, frames_budget: int | None = None) -> None:
        self._bytes_budget = bytes_budget
        self._frames_budget = frames_budget

    def set_hook(self, name: str, fn: Optional[Callable[..., None]]) -> None:
        if name not in self._hooks:
            raise ValueError(f"unknown hook '{name}'")
        self._hooks[name] = fn

    def set_detect_non4500(self, enabled: bool) -> None:
        self._detect_non4500 = bool(enabled)

    def clear_caches(self, kind: str | None = None) -> None:
        if kind in (None, "log"):
            self._last_log.clear()
        if kind in (None, "esp"):
            self._esp_stats.clear()
            self._spi_recent.clear()
        if kind in (None, "ike"):
            self._ike_stats.clear()
        if kind in (None, "budget"):
            self._bytes_seen = 0
            self._frames_seen = 0

    def snapshot_metrics(self) -> Dict[str, Any]:
        return {
            "bytes_seen": self._bytes_seen,
            "frames_seen": self._frames_seen,
            "esp_flows": len(self._esp_stats),
            "ike_flows": len(self._ike_stats),
            "summary_interval_s": self._summary_every,
            "detect_non4500": self._detect_non4500,
        }

    # Main entry
    def handle(self, packet: Packet, src_ip: str, dst_ip: str, sport: int, dport: int,
               inbound_iface=None) -> bool:
        """
        Returns True iff recognized/logged (caller decides forwarding).
        """
        # Budget checks (soft stop emitting logs but still return True if recognized)
        def under_budget(size: int) -> bool:
            if self._bytes_budget is not None and (self._bytes_seen + size) > self._bytes_budget:
                return False
            if self._frames_budget is not None and (self._frames_seen + 1) > self._frames_budget:
                return False
            return True

        # Datagram payload
        raw = self._get_raw(packet)
        size = len(raw)
        recognized = False

        # UDP paths first (4500/500)
        is_udp = hasattr(packet, "haslayer") and packet.haslayer(UDP)
        if is_udp and not (sport in (self.IKE, self.NAT_T) or dport in (self.IKE, self.NAT_T)):
            is_udp = False  # UDP but not our ports

        if is_udp:
            s_is_4500 = (sport == self.NAT_T)
            d_is_4500 = (dport == self.NAT_T)
            on_4500 = s_is_4500 or d_is_4500
            on_500  = (sport == self.IKE) or (dport == self.IKE)

            # 1) NAT-T keepalive: single 0xFF byte (UDP/4500)
            if on_4500 and size == 1 and raw == b"\xff":
                recognized = True
                if under_budget(size) and self._should_log(src_ip, sport, dst_ip, dport, "keepalive"):
                    self._safe_log(
                        f"[Transport][🛡 ESP] NAT-T keepalive {src_ip}:{sport} → {dst_ip}:{dport} on {inbound_iface}"
                    )
                self._tally(size)
                self._maybe_summary()
                return True

            # 2) Non-ESP marker (0x00000000) indicates IKE *over* UDP/4500 (RFC 3948/7296)
            if on_4500 and size >= 4 and raw[:4] == b"\x00\x00\x00\x00":
                # IKE header begins at offset 4
                if size >= 4 + 28:
                    try:
                        hdr = self._parse_ike_header(raw, offset=4)
                        recognized = True
                        self._emit_ike(src_ip, sport, dst_ip, dport, hdr, inbound_iface, size)
                        self._tally(size)
                        self._maybe_summary()
                        return True
                    except Exception as e:
                        recognized = True
                        self._emit_ike_min(src_ip, sport, dst_ip, dport, size, inbound_iface, note=f"parse_err={e!s}")
                        self._tally(size)
                        self._maybe_summary()
                        return True
                else:
                    recognized = True
                    self._emit_ike_min(src_ip, sport, dst_ip, dport, size, inbound_iface, note="short")
                    self._tally(size)
                    self._maybe_summary()
                    return True

            # 3) ESP over NAT-T (UDP/4500) WITHOUT Non-ESP marker: first 8 bytes are {SPI, SEQ}
            if on_4500 and size >= 8 and raw[:4] != b"\x00\x00\x00\x00":
                spi = int.from_bytes(raw[0:4], "big")
                seq = int.from_bytes(raw[4:8], "big")
                recognized = True
                self._emit_esp("NAT-T", src_ip, sport, dst_ip, dport, spi, seq, size, inbound_iface)
                self._tally(size)
                self._maybe_summary()
                return True

            # 4) IKEv2 on UDP/500
            if on_500 and size >= 28:
                try:
                    hdr = self._parse_ike_header(raw, offset=0)
                    recognized = True
                    self._emit_ike(src_ip, sport, dst_ip, dport, hdr, inbound_iface, size)
                except Exception as e:
                    recognized = True
                    self._emit_ike_min(src_ip, sport, dst_ip, dport, size, inbound_iface, note=f"parse_err={e!s}")
                self._tally(size)
                self._maybe_summary()
                return True

        # Native ESP (IP proto=50) if enabled
        if self._detect_non4500 and self._is_proto_esp(packet):
            # Transport ESP header is {SPI(4), SEQ(4), ...}
            if size >= 8:
                spi = int.from_bytes(raw[0:4], "big")
                seq = int.from_bytes(raw[4:8], "big")
                recognized = True
                self._emit_esp("ESP", src_ip, sport or 0, dst_ip, dport or 0, spi, seq, size, inbound_iface)
                self._tally(size)
                self._maybe_summary()
                return True
            else:
                recognized = True
                self._emit_anomaly(
                    f"[Transport][🛡 ESP] proto=50 short header {src_ip} → {dst_ip} ({size}B) on {inbound_iface}"
                )
                self._tally(size)
                self._maybe_summary()
                return True

        return recognized

    # ------------------- Internals -------------------

    def _emit_esp(self, kind: str, sip: str, sport: int, dip: str, dport: int,
                  spi: int, seq: int, plen: int, inbound_iface: Optional[str]) -> None:
        flow = self._canon((sip, sport), (dip, dport), spi)
        st = self._esp_stats[flow]
        st["pkts"] += 1
        st["bytes"] += int(plen)

        # direction / rekey tracking
        direction = "cs" if sport < dport else "sc"
        peers = tuple(sorted([sip, dip]))
        recent = self._spi_recent[(peers, direction)]
        if spi not in recent:
            if len(recent) >= recent.maxlen:  # window rollover implies possible churn
                self._emit_anomaly(
                    f"[Transport][🛡 ESP] SPI rotation (window full) {sip}:{sport} ↔ {dip}:{dport} on {inbound_iface}"
                )
            recent.append(spi)

        if self._should_log(sip, sport, dip, dport, f"esp|spi={spi:08x}"):
            self._safe_log(
                f"[Transport][🛡 ESP] {kind} SPI=0x{spi:08x} seq={seq} "
                f"{sip}:{sport} → {dip}:{dport} on {inbound_iface} | len={plen}B"
            )

        if self._hooks["esp"]:
            try:
                self._hooks["esp"]({
                    "kind": kind, "spi": spi, "seq": seq, "sip": sip, "sport": sport,
                    "dip": dip, "dport": dport, "len": plen, "iface": inbound_iface
                })
            except Exception:
                pass  # keep observer robust

    def _emit_ike(self, sip: str, sport: int, dip: str, dport: int,
                  hdr: Dict[str, Any], inbound_iface: Optional[str], plen: int) -> None:
        key = (sip, sport, dip, dport)
        st = self._ike_stats[key]
        st["pkts"] += 1
        st["bytes"] += int(plen)

        xname = self.IKE_X.get(hdr["exchange"], f"exchange={hdr['exchange']}")
        flags = hdr["flags"]
        flag_str = self._ike_flag_str(flags)

        if self._should_log(sip, sport, dip, dport, f"ike|{hdr['vmaj']}.{hdr['vmin']}|{xname}"):
            self._safe_log(
                f"[Transport][🔐 IKEv2] {xname} {sip}:{sport} → {dip}:{dport} | "
                f"v={hdr['vmaj']}.{hdr['vmin']} flags={flag_str} len={hdr['length']} on {inbound_iface}"
            )

        if self._hooks["ike"]:
            try:
                self._hooks["ike"]({
                    "sip": sip, "sport": sport, "dip": dip, "dport": dport,
                    "version": (hdr["vmaj"], hdr["vmin"]),
                    "exchange": hdr["exchange"], "flags": flags, "length": hdr["length"],
                    "msgid": hdr["msgid"], "iface": inbound_iface
                })
            except Exception:
                pass

    def _emit_ike_min(self, sip: str, sport: int, dip: str, dport: int,
                      plen: int, inbound_iface: Optional[str], note: str = "") -> None:
        if self._should_log(sip, sport, dip, dport, "ike-min"):
            n = f" | {note}" if note else ""
            self._safe_log(
                f"[Transport][🔐 IKEv2] message {sip}:{sport} → {dip}:{dport} | {plen}B on {inbound_iface}{n}"
            )

    def _emit_anomaly(self, msg: str) -> None:
        if self._hooks["anomaly"]:
            try:
                self._hooks["anomaly"]({"message": msg})
            except Exception:
                pass
        self._safe_log(msg)

    def _maybe_summary(self) -> None:
        now = time.time()
        if now - self._last_summary < self._summary_every:
            return
        self._last_summary = now

        # Coalesce per peer tuple for ESP
        totals = defaultdict(lambda: {"pkts": 0, "bytes": 0})
        for ((a, b), _spi), st in list(self._esp_stats.items()):
            totals[(a, b)]["pkts"] += st["pkts"]
            totals[(a, b)]["bytes"] += st["bytes"]

        for (a, b), st in totals.items():
            (sip, sp), (dip, dp) = a, b
            line = f"[Transport][🛡 ESP] summary {sip}:{sp} ↔ {dip}:{dp} | pkts={st['pkts']} bytes={st['bytes']}"
            self._safe_log(line)
            if self._hooks["summary"]:
                try:
                    self._hooks["summary"]({"type": "esp", "sip": sip, "sp": sp, "dip": dip, "dp": dp, **st})
                except Exception:
                    pass

        # IKE summary by 4-tuple
        for (sip, sp, dip, dp), st in list(self._ike_stats.items()):
            line = f"[Transport][🔐 IKEv2] summary {sip}:{sp} ↔ {dip}:{dp} | pkts={st['pkts']} bytes={st['bytes']}"
            self._safe_log(line)
            if self._hooks["summary"]:
                try:
                    self._hooks["summary"]({"type": "ike", "sip": sip, "sp": sp, "dip": dip, "dp": dp, **st})
                except Exception:
                    pass

    # --- helpers ---

    def _tally(self, size: int) -> None:
        self._bytes_seen += int(size)
        self._frames_seen += 1

    @staticmethod
    def _get_raw(pkt: Packet) -> bytes:
        try:
            if hasattr(pkt, "haslayer") and pkt.haslayer(Raw) and pkt[Raw].load:
                return bytes(pkt[Raw].load)
        except Exception:
            pass
        return b""

    @staticmethod
    def _is_proto_esp(pkt: Packet) -> bool:
        # IPv4: proto=50, IPv6: nh=50
        try:
            if hasattr(pkt, "haslayer") and pkt.haslayer(IP):
                ip = pkt[IP]
                return int(getattr(ip, "proto", -1)) == 50
            if hasattr(pkt, "haslayer") and pkt.haslayer(IPv6):
                ip6 = pkt[IPv6]
                return int(getattr(ip6, "nh", -1)) == 50
        except Exception:
            return False
        return False

    @staticmethod
    def _canon(a: Tuple[str,int], b: Tuple[str,int], spi: int):
        return (((a, b) if a <= b else (b, a)), int(spi) & 0xFFFFFFFF)

    def _should_log(self, sip, sp, dip, dp, tag: str = "") -> bool:
        k = f"{sip}:{sp}>{dip}:{dp}|{tag}"
        now = time.time()
        if now - self._last_log[k] >= self._log_window:
            self._last_log[k] = now
            return True
        return False

    @staticmethod
    def _ike_flag_str(flags: int) -> str:
        # Bit meanings (RFC 7296 §3.1): I=0x08, V=0x04, R=0x20 (reserved bits exist; keep hex too)
        parts = []
        if flags & 0x20: parts.append("R")   # Response
        if flags & 0x08: parts.append("I")   # Initiator
        if flags & 0x04: parts.append("V")   # Version
        parts.append(f"0x{flags:02x}")
        return "".join(parts)

    @staticmethod
    def _parse_ike_header(b: bytes, offset: int = 0) -> Dict[str, Any]:
        """
        Parse minimal IKEv2 header fields starting at b[offset].
        IKEv2 header is 28 bytes:
          Initiator SPI(8), Responder SPI(8), Next(1), Version(1), Exchange(1), Flags(1),
          MessageID(4), Length(4)
        """
        if len(b) < offset + 28:
            raise ValueError("short IKE header")
        i_spi = int.from_bytes(b[offset+0: offset+8], "big")
        r_spi = int.from_bytes(b[offset+8: offset+16], "big")
        version = b[offset + 17]
        vmaj, vmin = (version >> 4) & 0x0F, version & 0x0F
        exch   = b[offset + 18]
        flags  = b[offset + 19]
        msgid  = int.from_bytes(b[offset+20: offset+24], "big")
        length = int.from_bytes(b[offset+24: offset+28], "big")

        if vmaj != 2:  # sanity
            # allow logging but mark as anomaly
            # (IKEv1 would be v=1, but our focus is IKEv2 as per RFC 7296)
            pass

        return {
            "i_spi": i_spi, "r_spi": r_spi, "vmaj": vmaj, "vmin": vmin,
            "exchange": exch, "flags": flags, "msgid": msgid, "length": length
        }

    # logger shim to accept both your styles seen elsewhere
    def _safe_log(self, *args, **kwargs) -> None:
        try:
            # Accept either log_message(msg) or log_message(src, sport, dst, dport, kind, msg)
            if len(args) == 1 and isinstance(args[0], str):
                self.log.log_message(args[0])
            else:
                self.log.log_message(*args, **kwargs)
        except Exception:
            # last resort: try print to not disrupt pipeline
            try:
                print(args[0] if args else "[Transport][ESP] log")
            except Exception:
                pass
class TransportLLMNRManager:
    """
    LLMNR (UDP/5355) parser & logger (RFC 4795).

    Observes:
      • Queries and Responses for IPv4 and IPv6.
      • Parses QNAME/QTYPE and a preview of A/AAAA/PTR answers.
      • Logs flags (Conflict, Truncation, Tentative).

    Public API:
        handle(packet, src_ip, dst_ip, sport, dport, inbound_iface) -> bool
    """

    # --- Tunables ---
    LLMNR_PORT = 5355
    LOG_RPS: float = 0.5  # Global log rate
    LOG_BURST: int = 5  # Global burst
    SIG_COOLDOWN_S: float = 5.0  # Cooldown per (sig)
    GC_PERIOD_S: float = 60.0

    # --- Type/Code Names (subset) ---
    _QT = {1: "A", 12: "PTR", 28: "AAAA", 16: "TXT", 33: "SRV"}
    _RC = {0: "NoErr", 1: "FormErr", 2: "SrvFail", 3: "NXDomain", 5: "Refused"}

    class _TokenBucket:
        __slots__ = ("cap", "rate", "tokens", "last")

        def __init__(self, cap: int, rate: float):
            self.cap = max(1, int(cap));
            self.rate = max(0.1, float(rate))
            self.tokens = float(self.cap);
            self.last = time.time()

        def _refill(self):
            now = time.time();
            dt = now - self.last
            if dt > 0:
                self.tokens = min(self.cap, int(self.tokens + dt * self.rate));
                self.last = now

        def take(self, cost=1.0) -> bool:
            self._refill()
            if self.tokens >= cost:
                self.tokens -= cost;
                return True
            return False

    def __init__(self, router_logger):
        self.log = router_logger
        self._tb = self._TokenBucket(self.LOG_BURST, self.LOG_RPS)
        # key: (sig_tuple) -> next_ok_ts
        self._cooldown_until: Dict[Tuple, float] = {}
        self._last_gc = time.time()
        self.log.log_message("[Transport][🏘️ LLMNR] Manager ready.")

    # -------------------- Public Entry --------------------

    def handle(self, packet: "Packet", src_ip: str, dst_ip: str, sport: int, dport: int, inbound_iface: str) -> bool:
        if UDP is None:
            return False
        if not (sport == self.LLMNR_PORT or dport == self.LLMNR_PORT):
            return False
        if not packet.haslayer(UDP):
            return False

        # ✅ Get payload bytes regardless of Raw/LLMNR layers
        try:
            udp = packet[UDP]
            # bytes(udp.payload) returns the serialized payload even if it's LLMNRQuery/Response
            raw = bytes(udp.payload) if hasattr(udp, "payload") else b""
        except Exception:
            raw = b""

        if len(raw) < 12:  # DNS-style header minimum
            return False

        iface = (inbound_iface or "?").split("_")[-1]

        try:
            txid, flags, qd, an, ns, ar = struct.unpack("!HHHHHH", raw[0:12])
            qr = (flags >> 15) & 1
            op = (flags >> 11) & 0xF
            c_flag = bool((flags >> 10) & 1)  # Conflict
            tc_flag = bool((flags >> 9) & 1)  # Truncation
            t_flag = bool((flags >> 8) & 1)  # Tentative
            rcode = flags & 0xF

            qname, qtype, p_offset = self._parse_question(raw, 12, qd)

            sig_key = (src_ip, qname, qtype, qr)
            if not self._should_log(sig_key):
                self._maybe_gc()
                return True

            flag_parts = []
            if c_flag: flag_parts.append("Conflict")
            if tc_flag: flag_parts.append("TC")
            if t_flag: flag_parts.append("Tentative")
            flag_str = f" flags=[{','.join(flag_parts)}]" if flag_parts else ""

            if qr == 0:
                # Query
                self.log.log_message(
                    f"[Transport][🏘️ LLMNR][🔎 Query] if={iface} {src_ip}:{sport} → {dst_ip}:{dport} "
                    f"txid=0x{txid:04x} name={qname} type={self._QT.get(qtype, qtype)}{flag_str}"
                )
            else:
                # Response
                rcode_name = self._RC.get(rcode, f"RC{rcode}")
                answers = self._parse_answers(raw, p_offset, an)
                ans_str = ""
                if answers:
                    ans_preview = ", ".join(answers[:2])
                    more = f" +{len(answers) - 2} more" if len(answers) > 2 else ""
                    ans_str = f" | {ans_preview}{more}"

                self.log.log_message(
                    f"[Transport][🏘️ LLMNR][📦 Response] if={iface} {src_ip}:{sport} → {dst_ip}:{dport} "
                    f"txid=0x{txid:04x} rcode={rcode_name} an={an} q={qname}{flag_str}{ans_str}"
                )

        except Exception as e:
            sig_key = (src_ip, "parse-error")
            if self._should_log(sig_key):
                self.log.log_message(f"[Transport][🏘️ LLMNR] Parse Error on {iface} {src_ip}:{sport}: {e}")

        self._maybe_gc()
        return True

    # -------------------- Internals --------------------

    def _parse_question(self, buf: bytes, p: int, qdcount: int) -> Tuple[str, int, int]:
        """Parses the *first* question. Returns (name, type, new_offset)."""
        if qdcount == 0:
            return "-", 0, p

        name, p = self._read_dns_name(buf, p)
        if p + 4 > len(buf):
            return name, 0, p  # Truncated

        qtype = struct.unpack("!H", buf[p:p + 2])[0];
        p += 2
        qclass = struct.unpack("!H", buf[p:p + 2])[0];
        p += 2

        return name, qtype, p

    def _parse_answers(self, buf: bytes, p: int, ancount: int) -> List[str]:
        """Parses up to 3 answers into readable strings."""
        answers = []
        try:
            for _ in range(min(ancount, 3)):
                name, p = self._read_dns_name(buf, p)
                if p + 10 > len(buf): break  # Min RR size

                rtype, rclass, ttl, rdlen = struct.unpack("!HHIH", buf[p:p + 10]);
                p += 10
                rdata = buf[p:p + rdlen];
                p += rdlen

                t_str = self._QT.get(rtype, f"T{rtype}")
                val = "..."
                if rtype == 1:  # A
                    val = ".".join(str(b) for b in rdata)
                elif rtype == 28:  # AAAA
                    val = self._format_ipv6(rdata)
                elif rtype in (12, 5):  # PTR, CNAME
                    val, _ = self._read_dns_name(rdata, 0)

                answers.append(f"{t_str} {val} (ttl={ttl})")
        except Exception:
            pass  # Best effort
        return answers

    def _read_dns_name(self, buf: bytes, p: int) -> Tuple[str, int]:
        """Reads a DNS-compressed name. Returns (name, new_offset)."""
        labels = []
        orig_p = p
        jumped = False
        max_jumps = 10  # Avoid loops

        while max_jumps > 0:
            if p >= len(buf):
                return "??", p  # Truncated

            length = buf[p];
            p += 1
            if length == 0:
                if not jumped:
                    orig_p = p  # End of this label chain
                break

            if (length & 0xC0) == 0xC0:  # Pointer
                if p >= len(buf):
                    return "??", p  # Truncated pointer
                offset = ((length & 0x3F) << 8) | buf[p]
                if not jumped:
                    orig_p = p + 1  # Set return offset to *after* the pointer
                    jumped = True
                p = offset
                max_jumps -= 1
                continue

            if p + length > len(buf):
                return "??", p  # Truncated label

            labels.append(buf[p:p + length].decode("utf-8", "ignore"))
            p += length

        return ".".join(labels) or ".", orig_p

    def _format_ipv6(self, b16: bytes) -> str:
        try:
            return socket.inet_ntop(socket.AF_INET6, b16)
        except Exception:
            return ":".join(f"{b16[i:i + 2].hex()}" for i in range(0, 16, 2))

    def _should_log(self, sig: Tuple) -> bool:
        now = time.time()
        # 1. Per-signature cooldown
        until = self._cooldown_until.get(sig, 0.0)
        if now < until:
            return False
        # 2. Global token bucket
        if not self._tb.take():
            return False
        # Allow log
        self._cooldown_until[sig] = now + self.SIG_COOLDOWN_S
        return True

    def _maybe_gc(self):
        now = time.time()
        if now - self._last_gc < self.GC_PERIOD_S:
            return

        cutoff = now - (self.SIG_COOLDOWN_S * 5)  # Keep for 5x cooldown
        stale = [k for k, ts in self._cooldown_until.items() if ts < cutoff]
        for k in stale:
            self._cooldown_until.pop(k, None)

        self._last_gc = now
class TransportUndecodedManager:
    """
    Catch-all manager for undecoded transport packets.

    Goals:
      • Dedup + rate-limit logs
      • Quick heuristics (QUIC/RTP/STUN/Overlay-ish/DTLS-ish/TLS-ish)
      • Better support for UDP/889 LAN discovery/broadcast-like traffic
      • Optional promotion hooks (tell overlay tracker, etc.)
      • Short ring of payload samples per 5-tuple for debugging
      • Helpful snapshot() output for UI / debugging / blocks

    Notes on 889 support:
      - names the wire behavior, not a made-up vendor protocol
      - examples:
          udp889-directed-broadcast
          udp889-limited-broadcast
          udp889-multicast
          udp889-unicast
      - also extracts a few cheap structural hints from the payload
    """

    # --- Tunables ---
    LOG_RPS = 1.0
    LOG_BURST = 8
    FLOW_TTL = 300.0
    SAMPLE_RING = 6
    SIG_COOLDOWN_S = 5.0
    MAX_PREVIEW = 64
    PROMOTE_OVERLAY = True
    PROMOTE_TTL = 300.0

    # Ports/ranges for quick hints
    _STUN_PORTS = {3478, 5349}
    _QUIC_HINT_PORTS = {443, 853, 784, 8443}
    _RTP_PT_RANGE = range(96, 128)
    _HIGH_EPHEMERAL = (49152, 65535)

    class _TokenBucket:
        __slots__ = ("cap", "rate", "tokens", "last")

        def __init__(self, cap: int, rate: float):
            self.cap = max(1, int(cap))
            self.rate = max(0.1, float(rate))
            self.tokens = float(cap)
            self.last = time.time()

        def take(self, cost: float = 1.0) -> bool:
            now = time.time()
            dt = now - self.last
            if dt > 0:
                self.tokens = min(self.cap, self.tokens + dt * self.rate)
                self.last = now
            if self.tokens >= cost:
                self.tokens -= cost
                return True
            return False

    def __init__(self, router_logger, *, overlay_promoter=None):
        """
        overlay_promoter: optional callable(src_ip, sport, dst_ip, dport, ttl_seconds)
                          If set and a flow looks like overlay/P2P, we call it.
        """
        self.log = router_logger
        self.overlay_promoter = overlay_promoter

        self._tb = self._TokenBucket(self.LOG_BURST, self.LOG_RPS)
        self._cooldown_until: Dict[Tuple, float] = {}
        self._flows: Dict[Tuple, dict] = {}
        self._last_gc = time.time()

        self.log.log_message("[Transport][🧩 Undecoded] Manager ready.")

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def handle(
        self,
        packet: Packet,
        src_ip: str,
        dst_ip: str,
        sport: int,
        dport: int,
        iface_short: str,
        *,
        proto: str = "udp"
    ) -> bool:
        """
        Handles undecoded UDP/TCP packets. Always returns True (we consumed the event).
        """
        self._maybe_gc()
        now = time.time()
        k = self._canon_key(src_ip, sport, dst_ip, dport)

        info = self._flows.get(k)
        if not info:
            info = {
                "first": now,
                "last": now,
                "proto": proto,
                "cnt": 0,
                "samples": deque(maxlen=self.SAMPLE_RING),
                "tags": set(),
                "suspect": None,
                "guesses": {},
                "last_guess": None,
                "last_meta": {},
            }
            self._flows[k] = info
        else:
            info["last"] = now

        info["cnt"] += 1

        payload = self._raw_payload_or_empty(packet)
        payload_len = len(payload)
        l7_preview = payload[:self.MAX_PREVIEW].hex() if payload else ""
        ascii_preview = self._ascii_preview(payload[:48]) if payload else ""
        entropy = self._shannon_entropy(payload[:256]) if payload else 0.0

        meta = self._extract_meta(packet, src_ip, dst_ip, sport, dport, proto, payload)
        guess, tags, detail = self._guess(proto, src_ip, dst_ip, sport, dport, payload, packet, meta)

        if guess:
            info["last_guess"] = guess
            info["guesses"][guess] = int(info["guesses"].get(guess, 0)) + 1

        if tags:
            info["tags"].update(tags)

        info["last_meta"] = {
            "payload_len": payload_len,
            "entropy": round(entropy, 3),
            "detail": detail,
            "meta": meta,
        }

        if payload_len:
            info["samples"].append({
                "ts": now,
                "len": payload_len,
                "sha1_8": hashlib.sha1(payload).hexdigest()[:8],
                "entropy": round(entropy, 3),
                "guess": guess,
                "tags": sorted(tags),
                "detail": detail,
            })

        if guess == "overlay" and self.PROMOTE_OVERLAY and callable(self.overlay_promoter):
            try:
                self.overlay_promoter(src_ip, sport, dst_ip, dport, self.PROMOTE_TTL)
                info["suspect"] = "overlay"
            except Exception as e:
                self.log.log_message(f"[Transport][🧩 Undecoded] overlay_promoter error: {e}")

        sig = (proto, iface_short, sport, dport, guess, detail.get("flow_type"))
        if self._should_log(sig):
            human = (
                f"[Transport][🧩 Undecoded] if={iface_short} "
                f"{src_ip}:{sport} → {dst_ip}:{dport} | "
                f"{proto.upper()} len={payload_len} guess={guess or '-'}"
            )

            if tags:
                human += f" tags={','.join(sorted(tags))}"

            flow_type = detail.get("flow_type")
            if flow_type:
                human += f" flow={flow_type}"

            ttl = meta.get("ttl")
            if ttl is not None:
                human += f" ttl={ttl}"

            if detail.get("embedded_ipv4"):
                human += f" embedded_ip={detail['embedded_ipv4']}"

            if "zero_run_len" in detail:
                human += f" zero_pad={detail['zero_run_len']}"

            if "prefix_len" in detail:
                human += f" prefix={detail['prefix_len']}"

            if "tail_len" in detail:
                human += f" tail={detail['tail_len']}"

            if ascii_preview:
                human += f" ascii='{ascii_preview}'"

            if l7_preview:
                human += f" | l7[:{min(payload_len, self.MAX_PREVIEW)}]={l7_preview}"

            self.log.log_message(human)

        return True

    # ------------------------------------------------------------------
    # Heuristics
    # ------------------------------------------------------------------

    def _guess(
        self,
        proto: str,
        src_ip: str,
        dst_ip: str,
        sport: int,
        dport: int,
        payload: bytes,
        pkt: Packet,
        meta: dict,
    ) -> Tuple[Optional[str], set, dict]:
        """
        Return:
          (guess, tags, detail)

        guess examples:
          overlay, stun, quic, rtp, dtls, keepalive, tls, unknown,
          udp889-directed-broadcast, udp889-limited-broadcast,
          udp889-multicast, udp889-unicast
        """
        payload_len = len(payload)
        tags = set()
        detail: Dict[str, Any] = {}

        # --- UDP first ---
        if proto == "udp":
            # Strong special-case for port 889
            if sport == 889 or dport == 889:
                guess_889, tags_889, detail_889 = self._guess_udp889(src_ip, dst_ip, sport, dport, payload, pkt, meta)
                tags.update(tags_889)
                detail.update(detail_889)
                return guess_889, tags, detail

            # Overlay / ZeroTier-ish
            if self._looks_like_overlay_flow(sport, dport, payload_len):
                tags.add("p2p")
                return "overlay", tags, detail

            # STUN
            if (sport in self._STUN_PORTS) or (dport in self._STUN_PORTS) or self._looks_like_stun(payload):
                tags.update({"nat-traversal", "binary"})
                return "stun", tags, detail

            # QUIC
            if (sport in self._QUIC_HINT_PORTS) or (dport in self._QUIC_HINT_PORTS) or self._looks_like_quic(payload):
                tags.update({"http3", "binary"})
                return "quic", tags, detail

            # RTP
            if self._looks_like_rtp(payload):
                tags.update({"voip", "media"})
                return "rtp", tags, detail

            # DTLS
            if self._looks_like_dtls(payload):
                tags.update({"tls", "binary"})
                return "dtls", tags, detail

            # Tiny keepalive-ish
            if payload_len in (0, 1, 4, 8):
                tags.add("tiny")
                return "keepalive", tags, detail

            # Some cheap generic labels
            if payload_len >= 1024 and self._long_zero_run(payload, min_run=128):
                tags.add("padded")
            if self._find_embedded_rfc1918_ipv4(payload) is not None:
                tags.add("rfc1918")

            return "unknown", tags, detail

        # --- TCP ---
        if proto == "tcp":
            if self._looks_like_tls_on_tcp(payload):
                tags.update({"tls", "binary"})
                return "tls", tags, detail
            return "unknown", tags, detail

        return "unknown", tags, detail

    def _guess_udp889(
        self,
        src_ip: str,
        dst_ip: str,
        sport: int,
        dport: int,
        payload: bytes,
        pkt: Packet,
        meta: dict,
    ) -> Tuple[str, set, dict]:
        tags = {"udp889", "binary"}
        detail: Dict[str, Any] = {}

        ttl = meta.get("ttl")
        dst_mac = (meta.get("dst_mac") or "").lower()
        payload_len = len(payload)

        flow_type = self._classify_udp889_flow(dst_ip, dst_mac)
        detail["flow_type"] = flow_type

        if ttl == 1:
            tags.add("local-segment")

        if flow_type.endswith("broadcast") or "broadcast" in flow_type:
            tags.add("broadcast")
        if "multicast" in flow_type:
            tags.add("multicast")
        if flow_type.endswith("unicast"):
            tags.add("unicast")

        if payload_len >= 1024:
            tags.add("large")

        # Extract a structural summary from the payload
        shape = self._analyze_889_payload(payload)
        detail.update(shape)

        if shape.get("embedded_ipv4"):
            tags.add("embedded-ip")
        if shape.get("zero_run_len", 0) >= 64:
            tags.add("padded")
        if shape.get("mostly_zero"):
            tags.add("mostly-zero")
        if shape.get("tail_u32_le"):
            tags.add("trailer")

        # Give the flow a stable guess string
        return flow_type, tags, detail

    # ------------------------------------------------------------------
    # 889 helpers
    # ------------------------------------------------------------------

    def _classify_udp889_flow(self, dst_ip: str, dst_mac: str) -> str:
        if dst_ip == "255.255.255.255":
            return "udp889-limited-broadcast"

        if self._is_directed_broadcast_ip(dst_ip):
            return "udp889-directed-broadcast"

        if self._is_ipv4_multicast(dst_ip):
            return "udp889-multicast"

        return "udp889-unicast"

    def _analyze_889_payload(self, payload: bytes) -> dict:
        if not payload:
            return {
                "prefix_len": 0,
                "zero_run_len": 0,
                "tail_len": 0,
                "mostly_zero": False,
                "embedded_ipv4": None,
                "tail_u32_le": [],
            }

        first_zero = None
        for i, b in enumerate(payload):
            if b == 0:
                first_zero = i
                break

        if first_zero is None:
            prefix_len = len(payload)
            zero_run_len = 0
            tail = b""
        else:
            prefix_len = first_zero

            # Find end trailer after long zero region
            tail_start = len(payload)
            probe = len(payload) - 1

            while probe >= first_zero and payload[probe] == 0:
                probe -= 1

            if probe < first_zero:
                tail_start = len(payload)
            else:
                while probe >= first_zero and payload[probe] != 0:
                    probe -= 1
                tail_start = probe + 1

            zero_run_len = max(0, tail_start - prefix_len)
            tail = payload[tail_start:]

        embedded_ipv4 = self._find_embedded_rfc1918_ipv4(payload)

        zero_count = payload.count(0)
        mostly_zero = (zero_count / max(1, len(payload))) >= 0.70

        tail_u32_le = []
        if tail:
            usable = len(tail) - (len(tail) % 4)
            for i in range(0, usable, 4):
                tail_u32_le.append(int.from_bytes(tail[i:i + 4], "little"))

        return {
            "prefix_len": prefix_len,
            "zero_run_len": zero_run_len,
            "tail_len": len(tail),
            "mostly_zero": mostly_zero,
            "embedded_ipv4": embedded_ipv4,
            "tail_u32_le": tail_u32_le[:8],
        }

    def _is_directed_broadcast_ip(self, ip: str) -> bool:
        parts = ip.split(".")
        if len(parts) != 4:
            return False
        try:
            octets = [int(x) for x in parts]
        except ValueError:
            return False
        return octets[3] == 255 and ip != "255.255.255.255"

    def _is_ipv4_multicast(self, ip: str) -> bool:
        try:
            first = int(ip.split(".")[0])
            return 224 <= first <= 239
        except Exception:
            return False

    # ------------------------------------------------------------------
    # Generic payload signatures
    # ------------------------------------------------------------------

    def _looks_like_overlay_flow(self, sport: int, dport: int, payload_len: int) -> bool:
        lo, hi = self._HIGH_EPHEMERAL
        return (lo <= sport <= hi) and (lo <= dport <= hi) and payload_len in (59, 67, 137)

    def _looks_like_stun(self, payload: bytes) -> bool:
        if len(payload) < 8:
            return False
        return payload[4:8] == b"\x21\x12\xA4\x42"

    def _looks_like_quic(self, payload: bytes) -> bool:
        if len(payload) < 7:
            return False
        b0 = payload[0]
        if b0 & 0x80:
            try:
                ver = struct.unpack_from("!I", payload, 1)[0]
                return ver != 0
            except Exception:
                return False
        return False

    def _looks_like_rtp(self, payload: bytes) -> bool:
        if len(payload) < 12:
            return False
        b0 = payload[0]
        v = (b0 >> 6) & 0x03
        if v != 2:
            return False
        pt = payload[1] & 0x7F
        return pt in self._RTP_PT_RANGE

    def _looks_like_dtls(self, payload: bytes) -> bool:
        if len(payload) < 13:
            return False
        ct = payload[0]
        if ct not in (0x14, 0x16, 0x17):
            return False
        ver = (payload[1] << 8) | payload[2]
        return ver in (0x0301, 0x0302, 0x0303, 0x0304)

    def _looks_like_tls_on_tcp(self, payload: bytes) -> bool:
        if len(payload) < 5:
            return False
        ct = payload[0]
        if ct not in (0x14, 0x16, 0x17):
            return False
        ver = (payload[1] << 8) | payload[2]
        return ver in (0x0301, 0x0302, 0x0303, 0x0304)

    # ------------------------------------------------------------------
    # Meta / parsing helpers
    # ------------------------------------------------------------------

    def _extract_meta(
        self,
        packet: Packet,
        src_ip: str,
        dst_ip: str,
        sport: int,
        dport: int,
        proto: str,
        payload: bytes,
    ) -> dict:
        ttl = None
        src_mac = ""
        dst_mac = ""

        try:
            eth = packet.getlayer(Ether)
            if eth is not None:
                src_mac = str(getattr(eth, "src", "") or "")
                dst_mac = str(getattr(eth, "dst", "") or "")
        except Exception:
            pass

        try:
            ip = packet.getlayer(IP)
            if ip is not None and hasattr(ip, "ttl"):
                ttl = int(ip.ttl)
        except Exception:
            pass

        return {
            "ttl": ttl,
            "src_mac": src_mac,
            "dst_mac": dst_mac,
            "src_ip": src_ip,
            "dst_ip": dst_ip,
            "sport": int(sport),
            "dport": int(dport),
            "proto": proto,
            "payload_len": len(payload),
        }

    def _raw_payload_or_empty(self, packet: Packet) -> bytes:
        try:
            if packet is None:
                return b""
            if Raw in packet:
                return bytes(packet[Raw].load or b"")
        except Exception:
            return b""
        return b""

    def _find_embedded_rfc1918_ipv4(self, payload: bytes) -> Optional[str]:
        limit = min(len(payload) - 3, 256)
        for i in range(max(0, limit)):
            a, b, c, d = payload[i:i + 4]
            if a == 10:
                return f"{a}.{b}.{c}.{d}"
            if a == 172 and 16 <= b <= 31:
                return f"{a}.{b}.{c}.{d}"
            if a == 192 and b == 168:
                return f"{a}.{b}.{c}.{d}"
        return None

    def _long_zero_run(self, payload: bytes, *, min_run: int = 64) -> bool:
        run = 0
        for b in payload:
            if b == 0:
                run += 1
                if run >= min_run:
                    return True
            else:
                run = 0
        return False

    def _ascii_preview(self, data: bytes) -> str:
        if not data:
            return ""
        out = []
        for b in data:
            if 32 <= b <= 126:
                out.append(chr(b))
            else:
                out.append(".")
        return "".join(out)

    def _shannon_entropy(self, data: bytes) -> float:
        if not data:
            return 0.0
        counts = {}
        for b in data:
            counts[b] = counts.get(b, 0) + 1
        total = float(len(data))
        ent = 0.0
        for c in counts.values():
            p = c / total
            ent -= p * math.log2(p)
        return ent

    # ------------------------------------------------------------------
    # Logging / GC
    # ------------------------------------------------------------------

    def _canon_key(self, sip: str, sp: int, dip: str, dp: int):
        a = (sip, int(sp))
        b = (dip, int(dp))
        return (a, b) if a <= b else (b, a)

    def _should_log(self, sig: Tuple) -> bool:
        now = time.time()
        if not self._tb.take():
            return False
        until = self._cooldown_until.get(sig, 0.0)
        if now < until:
            return False
        self._cooldown_until[sig] = now + self.SIG_COOLDOWN_S
        return True

    def _maybe_gc(self):
        now = time.time()
        if now - self._last_gc < 30.0:
            return

        cutoff = now - self.FLOW_TTL

        stale = [k for k, v in self._flows.items() if v.get("last", 0) < cutoff]
        for k in stale:
            self._flows.pop(k, None)

        cool_cut = now - (self.SIG_COOLDOWN_S * 5)
        cold = [k for k, ts in self._cooldown_until.items() if ts < cool_cut]
        for k in cold:
            self._cooldown_until.pop(k, None)

        self._last_gc = now

    # ------------------------------------------------------------------
    # Introspection
    # ------------------------------------------------------------------

    def snapshot(self) -> dict:
        out = []
        for (a, b), v in self._flows.items():
            out.append({
                "a": a,
                "b": b,
                "proto": v["proto"],
                "cnt": v["cnt"],
                "first": v["first"],
                "last": v["last"],
                "tags": sorted(v["tags"]),
                "suspect": v.get("suspect"),
                "last_guess": v.get("last_guess"),
                "guesses": dict(v.get("guesses", {})),
                "last_meta": v.get("last_meta", {}),
                "samples": list(v["samples"]),
            })
        return {
            "flows": out,
            "cooldowns": len(self._cooldown_until),
        }
class TransportIkeManager:
    """
    Passive IKE / ISAKMP observer for UDP/500 and UDP/4500.

    What it handles
    ---------------
    - IKEv1 / ISAKMP on UDP/500
    - IKEv2 on UDP/500
    - IKE over NAT-T on UDP/4500 when the Non-ESP marker is present
    - NAT-T keepalives on UDP/4500 (single 0xFF)

    What it intentionally does *not* consume
    ----------------------------------------
    - ESP-in-UDP on 4500 when there is no Non-ESP marker. That traffic should be
      left for your ESP / NAT-T observer so managers do not fight each other.

    Public API
    ----------
    - handle(packet, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool
    - handle_udp(packet, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool
    - snapshot_metrics() -> dict
    - snapshot_flows(limit=200) -> dict
    - clear_caches() -> None
    - set_hook(name, fn) -> None     # name in {"ike", "keepalive", "anomaly", "summary"}
    - set_detect_offport(enabled) -> None

    Notes
    -----
    - This is budgeted / peek-oriented. It does not attempt full crypto parsing.
    - It can walk a few generic payload headers when the message is not clearly
      encrypted, which gives you useful summaries like SA/KE/Nonce/Notify/VendorID.
    - It recognizes IKEv1 and IKEv2 using the common 28-byte ISAKMP/IKE header.
    """

    FLOW_TTL_SEC = 15 * 60
    FLOW_SOFT_MAX = 50_000
    RL_INTERVAL_SEC = 1.0
    BYTES_BUDGET = 2048
    PAYLOAD_WALK_LIMIT = 8

    PORT_IKE = 500
    PORT_NATT = 4500

    # Common header is always 28 bytes.
    IKE_HDR_LEN = 28

    IKEV1_EXCHANGE_NAMES = {
        1: "Base",
        2: "IdentityProtection",
        3: "AuthenticationOnly",
        4: "Aggressive",
        5: "Informational",
        32: "QuickMode",
        33: "NewGroupMode",
        34: "Acknowledged",
    }

    IKEV2_EXCHANGE_NAMES = {
        34: "IKE_SA_INIT",
        35: "IKE_AUTH",
        36: "CREATE_CHILD_SA",
        37: "INFORMATIONAL",
        38: "IKE_SESSION_RESUME",
        43: "IKE_INTERMEDIATE",
    }

    IKEV1_PAYLOAD_NAMES = {
        0: "None",
        1: "SA",
        2: "Proposal",
        3: "Transform",
        4: "KE",
        5: "ID",
        6: "CERT",
        7: "CR",
        8: "HASH",
        9: "SIG",
        10: "Nonce",
        11: "Notify",
        12: "Delete",
        13: "VendorID",
        14: "Attr",
        15: "NAT-D",
        16: "NAT-OA",
    }

    IKEV2_PAYLOAD_NAMES = {
        0: "None",
        33: "SA",
        34: "KE",
        35: "IDi",
        36: "IDr",
        37: "CERT",
        38: "CERTREQ",
        39: "AUTH",
        40: "Nonce",
        41: "Notify",
        42: "Delete",
        43: "VendorID",
        44: "TSi",
        45: "TSr",
        46: "SK",
        47: "CP",
        48: "EAP",
        49: "GSPM",
        50: "IDG",
        53: "SKF",
        54: "PS",
    }

    IKEV2_NOTIFY_NAMES = {
        16384: "INITIAL_CONTACT",
        16386: "SET_WINDOW_SIZE",
        16387: "ADDITIONAL_TS_POSSIBLE",
        16388: "NAT_DETECTION_SOURCE_IP",
        16389: "NAT_DETECTION_DESTINATION_IP",
        16390: "COOKIE",
        16391: "USE_TRANSPORT_MODE",
        16393: "REKEY_SA",
        16394: "ESP_TFC_PADDING_NOT_SUPPORTED",
        16396: "NON_FIRST_FRAGMENTS_ALSO",
        16401: "MOBIKE_SUPPORTED",
        16403: "NO_ADDITIONAL_ADDRESSES",
        16404: "UPDATE_SA_ADDRESSES",
        16405: "COOKIE2",
        16406: "NO_NATS_ALLOWED",
        16407: "AUTH_LIFETIME",
        16417: "SIGNATURE_HASH_ALGORITHMS",
        16430: "IKEV2_FRAGMENTATION_SUPPORTED",
        16431: "SIGNATURE_HASH_ALGORITHMS_CERT",
    }

    def __init__(
        self,
        logger,
        *,
        detect_offport: bool = False,
        bytes_budget: int = BYTES_BUDGET,
        flow_ttl_sec: int = FLOW_TTL_SEC,
        flow_soft_max: int = FLOW_SOFT_MAX,
    ):
        self.logger = logger
        self.detect_offport = bool(detect_offport)
        self.peek_cap = max(128, int(bytes_budget or self.BYTES_BUDGET))
        self.flow_ttl_sec = max(60, int(flow_ttl_sec or self.FLOW_TTL_SEC))
        self.flow_soft_max = max(1024, int(flow_soft_max or self.FLOW_SOFT_MAX))

        self._lock = threading.RLock()
        self._flows: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        self._last_gc = time.time()
        self._last_summary = time.time()
        self._summary_every = 60.0

        self._metrics = {
            "seen": 0,
            "matched_udp": 0,
            "ikev1": 0,
            "ikev2": 0,
            "natt": 0,
            "natt_keepalive": 0,
            "natt_non_esp": 0,
            "partial": 0,
            "notify": 0,
            "nat_detect": 0,
            "vendor_id": 0,
            "retransmit_suspect": 0,
            "invalid": 0,
            "anomalies": 0,
            "flow_cache_evictions": 0,
            "active_flows": 0,
            "errors": 0,
        }

        self._hooks: Dict[str, Optional[Callable[..., None]]] = {
            "ike": None,
            "keepalive": None,
            "anomaly": None,
            "summary": None,
        }

        self._safe_log("[Transport][🔐 IKE] Manager ready.")

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def handle(self, packet, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool:
        return self.handle_udp(packet, src_ip, dst_ip, sport, dport, inbound_iface)

    def handle_udp(self, packet, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool:
        try:
            sport_i = self._safe_port(sport)
            dport_i = self._safe_port(dport)
            if sport_i is None or dport_i is None:
                return False

            payload = self._extract_udp_payload(packet)
            if payload is None:
                return False

            on_known_port = self._port_hit(self.PORT_IKE, (sport_i, dport_i)) or self._port_hit(self.PORT_NATT, (sport_i, dport_i))
            if not on_known_port and not self.detect_offport:
                return False

            if not on_known_port and self.detect_offport and not self._quick_ike_signature(payload):
                return False

            parsed = self._parse_datagram(payload, sport_i, dport_i)
            if not parsed:
                return False

            # Intentionally leave ESP-in-UDP/4500 to the ESP manager.
            if parsed.get("kind") == "esp-natt":
                return False

            now = time.time()
            key = self._flow_key(src_ip, sport_i, dst_ip, dport_i)
            iface = self._iface_suffix(inbound_iface)

            with self._lock:
                st = self._flows.get(key)
                if st is None:
                    st = {
                        "first": now,
                        "last": now,
                        "last_log": 0.0,
                        "hits": 0,
                        "initiator": None,
                        "responder": None,
                        "version": None,
                        "last_msgid": None,
                        "last_summary": None,
                        "nat_t": False,
                        "is_response_seen": False,
                        "history": deque(maxlen=12),
                    }
                    self._flows[key] = st
                else:
                    st["last"] = now

                self._metrics["seen"] += 1
                st["hits"] = int(st.get("hits", 0) or 0) + 1

                kind = parsed.get("kind")
                if kind == "keepalive":
                    self._metrics["matched_udp"] += 1
                    self._metrics["natt_keepalive"] += 1
                    st["nat_t"] = True
                    st["last_summary"] = {
                        "kind": "keepalive",
                        "detail": "NAT-T keepalive",
                    }
                    do_log = self._should_log_locked(st, now)
                elif kind == "ike":
                    info = dict(parsed.get("info") or {})
                    st["nat_t"] = bool(info.get("nat_t")) or bool(st.get("nat_t"))
                    st["version"] = info.get("version_name") or st.get("version")
                    self._learn_orientation_locked(st, src_ip, sport_i, dst_ip, dport_i, info)
                    self._update_retransmit_locked(st, info)
                    st["last_summary"] = info
                    try:
                        st["history"].append({
                            "ts": now,
                            "msgid": info.get("msgid"),
                            "exchange": info.get("exchange_name"),
                            "flags": info.get("flags_text"),
                            "payloads": list(info.get("payload_names") or []),
                        })
                    except Exception:
                        pass

                    version_name = info.get("version_name")
                    self._metrics["matched_udp"] += 1
                    if version_name == "IKEv1":
                        self._metrics["ikev1"] += 1
                    elif version_name == "IKEv2":
                        self._metrics["ikev2"] += 1
                    if info.get("nat_t"):
                        self._metrics["natt"] += 1
                        self._metrics["natt_non_esp"] += 1
                    if info.get("partial"):
                        self._metrics["partial"] += 1
                    if info.get("has_notify"):
                        self._metrics["notify"] += 1
                    if info.get("nat_detected"):
                        self._metrics["nat_detect"] += 1
                    if info.get("vendor_id_count"):
                        self._metrics["vendor_id"] += int(info.get("vendor_id_count") or 0)
                    do_log = self._should_log_locked(st, now)
                else:
                    self._metrics["invalid"] += 1
                    do_log = self._should_log_locked(st, now)

                self._metrics["active_flows"] = len(self._flows)
                self._clean_if_needed_locked(now)

            if parsed.get("kind") == "keepalive":
                if do_log:
                    self._safe_log(
                        f"[Transport][🚀 UDP][🔐 IKE] NAT-T keepalive {src_ip}:{sport_i} → {dst_ip}:{dport_i} on {iface}"
                    )
                self._emit_hook("keepalive", {
                    "src_ip": src_ip,
                    "dst_ip": dst_ip,
                    "sport": sport_i,
                    "dport": dport_i,
                    "iface": iface,
                })
                self._maybe_emit_summary(now)
                return True

            if parsed.get("kind") == "ike":
                info = dict(parsed.get("info") or {})
                if do_log:
                    self._log_ike(src_ip, sport_i, dst_ip, dport_i, iface, info)
                self._emit_hook("ike", {
                    "src_ip": src_ip,
                    "dst_ip": dst_ip,
                    "sport": sport_i,
                    "dport": dport_i,
                    "iface": iface,
                    **info,
                })
                if info.get("anomalies"):
                    self._emit_hook("anomaly", {
                        "src_ip": src_ip,
                        "dst_ip": dst_ip,
                        "sport": sport_i,
                        "dport": dport_i,
                        "iface": iface,
                        "anomalies": list(info.get("anomalies") or []),
                        **info,
                    })
                self._maybe_emit_summary(now)
                return True

            return False

        except Exception:
            with self._lock:
                self._metrics["errors"] += 1
            return False

    def snapshot_metrics(self) -> dict:
        with self._lock:
            out = dict(self._metrics)
            out["active_flows"] = len(self._flows)
            return out

    def snapshot_flows(self, limit: int = 200) -> dict:
        with self._lock:
            items = sorted(
                self._flows.items(),
                key=lambda kv: float(kv[1].get("last", 0.0) or 0.0),
                reverse=True,
            )[: max(1, int(limit))]

            flows = []
            for key, st in items:
                sip, sport, dip, dport = key
                flows.append({
                    "src_ip": sip,
                    "sport": int(sport),
                    "dst_ip": dip,
                    "dport": int(dport),
                    "first": float(st.get("first", 0.0) or 0.0),
                    "last": float(st.get("last", 0.0) or 0.0),
                    "hits": int(st.get("hits", 0) or 0),
                    "initiator": st.get("initiator"),
                    "responder": st.get("responder"),
                    "version": st.get("version"),
                    "nat_t": bool(st.get("nat_t")),
                    "last_msgid": st.get("last_msgid"),
                    "last_summary": st.get("last_summary"),
                    "history": list(st.get("history") or []),
                })

            return {"flows": flows}

    def clear_caches(self) -> None:
        with self._lock:
            self._flows.clear()
            self._metrics["active_flows"] = 0

    def set_hook(self, name: str, fn: Optional[Callable[..., None]]) -> None:
        if name not in self._hooks:
            raise ValueError(f"Unsupported hook '{name}'")
        self._hooks[name] = fn

    def set_detect_offport(self, enabled: bool) -> None:
        self.detect_offport = bool(enabled)

    # ------------------------------------------------------------------
    # Datagram parsing
    # ------------------------------------------------------------------
    def _parse_datagram(self, payload: bytes, sport: int, dport: int) -> Optional[Dict[str, Any]]:
        if payload is None:
            return None

        raw = bytes(payload[: self.peek_cap])
        if not raw:
            return None

        nat_t = False
        offset = 0
        on_500 = self._port_hit(self.PORT_IKE, (sport, dport))
        on_4500 = self._port_hit(self.PORT_NATT, (sport, dport))

        # UDP/4500 NAT-T keepalive is literally one 0xFF byte.
        if on_4500 and len(raw) == 1 and raw[0] == 0xFF:
            return {"kind": "keepalive"}

        if on_4500:
            if len(raw) >= 4 and raw[:4] == b"\x00\x00\x00\x00":
                nat_t = True
                offset = 4
            else:
                # Likely ESP-in-UDP rather than IKE. Do not consume here.
                return {"kind": "esp-natt"}
        elif on_500:
            offset = 0
        elif self.detect_offport:
            if len(raw) >= 4 and raw[:4] == b"\x00\x00\x00\x00":
                nat_t = True
                offset = 4
            else:
                offset = 0
        else:
            return None

        parsed = self._parse_ike_header(raw[offset:])
        if not parsed:
            return None

        parsed["nat_t"] = nat_t
        parsed["udp_offset"] = offset
        return {"kind": "ike", "info": parsed}

    def _parse_ike_header(self, raw: bytes) -> Optional[Dict[str, Any]]:
        if len(raw) < self.IKE_HDR_LEN:
            return None

        try:
            i_spi = raw[0:8]
            r_spi = raw[8:16]
            next_payload = raw[16]
            ver_byte = raw[17]
            exch = raw[18]
            flags = raw[19]
            msgid = int.from_bytes(raw[20:24], "big", signed=False)
            total_len = int.from_bytes(raw[24:28], "big", signed=False)

            major = (ver_byte >> 4) & 0x0F
            minor = ver_byte & 0x0F
            if major not in (1, 2):
                return None
            if total_len < self.IKE_HDR_LEN:
                return None

            version_name = "IKEv2" if major == 2 else "IKEv1"
            exchange_name = self._exchange_name(version_name, exch)
            next_payload_name = self._payload_name(version_name, next_payload)
            flags_text = self._flags_text(version_name, flags)
            partial = total_len > len(raw)

            payload_walk = self._walk_payload_chain(
                raw=raw,
                version_name=version_name,
                first_payload=next_payload,
                header_flags=flags,
                total_len=min(total_len, len(raw)),
            )

            payload_names = self._dedup_preserve([p.get("name") for p in payload_walk if p.get("name")])
            anomalies: List[str] = []
            if partial:
                anomalies.append("partial")
            if total_len > self.peek_cap:
                anomalies.append("oversize")
            if version_name == "IKEv1" and major == 1 and minor > 0:
                anomalies.append("legacy-version")

            notify_names = [p.get("notify_name") for p in payload_walk if p.get("notify_name")]
            nat_detected = any(
                name in ("NAT_DETECTION_SOURCE_IP", "NAT_DETECTION_DESTINATION_IP", "NAT-D")
                for name in notify_names
            )
            has_notify = any(p.get("type") == "Notify" for p in payload_walk)
            vendor_id_count = sum(1 for p in payload_walk if p.get("type") == "VendorID")
            if nat_detected:
                anomalies.append("nat-detect")

            info = {
                "version_name": version_name,
                "version": f"{major}.{minor}",
                "major": major,
                "minor": minor,
                "exchange": exch,
                "exchange_name": exchange_name,
                "next_payload": next_payload,
                "next_payload_name": next_payload_name,
                "flags": flags,
                "flags_text": flags_text,
                "msgid": msgid,
                "length": total_len,
                "partial": partial,
                "i_spi": i_spi.hex(),
                "r_spi": r_spi.hex(),
                "is_response": bool(flags & 0x20) if version_name == "IKEv2" else False,
                "is_initiator": bool(flags & 0x08) if version_name == "IKEv2" else None,
                "nat_t": False,
                "payloads": payload_walk,
                "payload_names": payload_names,
                "notify_names": self._dedup_preserve(notify_names),
                "has_notify": has_notify,
                "nat_detected": nat_detected,
                "vendor_id_count": vendor_id_count,
                "anomalies": self._dedup_preserve(anomalies),
            }
            return info
        except Exception:
            return None

    def _walk_payload_chain(
        self,
        *,
        raw: bytes,
        version_name: str,
        first_payload: int,
        header_flags: int,
        total_len: int,
    ) -> List[Dict[str, Any]]:
        # If the message is clearly encrypted already, do not pretend we can walk it.
        if version_name == "IKEv1" and (header_flags & 0x01):
            return []

        out: List[Dict[str, Any]] = []
        payload_type = int(first_payload)
        cursor = self.IKE_HDR_LEN
        hard_end = min(len(raw), int(total_len))
        steps = 0

        while payload_type != 0 and steps < self.PAYLOAD_WALK_LIMIT:
            steps += 1
            if cursor + 4 > hard_end:
                break

            next_type = raw[cursor]
            flags_reserved = raw[cursor + 1]
            plen = int.from_bytes(raw[cursor + 2:cursor + 4], "big", signed=False)
            if plen < 4:
                break
            if cursor + plen > hard_end:
                plen = hard_end - cursor
                if plen < 4:
                    break

            body = raw[cursor + 4: cursor + plen]
            name = self._payload_name(version_name, payload_type)
            entry: Dict[str, Any] = {
                "id": int(payload_type),
                "type": name,
                "name": name,
                "next": self._payload_name(version_name, next_type),
                "length": int(plen),
                "critical": bool(flags_reserved & 0x80) if version_name == "IKEv2" else False,
            }

            if name == "Notify":
                notify = self._parse_notify_payload(version_name, body)
                if notify:
                    entry.update(notify)
            elif name == "VendorID":
                entry["vendor_len"] = len(body)
            elif name == "Nonce":
                entry["nonce_len"] = len(body)
            elif name in ("KE", "SA", "TSi", "TSr", "CP", "EAP", "HASH", "SIG", "CERT"):
                entry["body_len"] = len(body)

            out.append(entry)

            # In IKEv2, SK / SKF means everything after is encrypted / fragmented.
            if version_name == "IKEv2" and name in ("SK", "SKF"):
                break

            payload_type = next_type
            cursor += plen

        return out

    def _parse_notify_payload(self, version_name: str, body: bytes) -> Optional[Dict[str, Any]]:
        try:
            if version_name == "IKEv2":
                if len(body) < 4:
                    return None
                protocol_id = body[0]
                spi_size = body[1]
                notify_type = int.from_bytes(body[2:4], "big", signed=False)
                if len(body) < 4 + spi_size:
                    return None
                notify_name = self.IKEV2_NOTIFY_NAMES.get(notify_type, f"Notify({notify_type})")
                return {
                    "notify_type": notify_type,
                    "notify_name": notify_name,
                    "protocol_id": protocol_id,
                    "spi_size": spi_size,
                }

            # IKEv1 Notify payload layout begins with DOI(4), Protocol-ID(1), SPI Size(1), Message Type(2)
            if version_name == "IKEv1":
                if len(body) < 8:
                    return None
                doi = int.from_bytes(body[0:4], "big", signed=False)
                protocol_id = body[4]
                spi_size = body[5]
                notify_type = int.from_bytes(body[6:8], "big", signed=False)
                return {
                    "notify_type": notify_type,
                    "notify_name": f"Notify({notify_type})",
                    "protocol_id": protocol_id,
                    "spi_size": spi_size,
                    "doi": doi,
                }
        except Exception:
            return None
        return None

    # ------------------------------------------------------------------
    # Flow tracking / metrics
    # ------------------------------------------------------------------
    def _learn_orientation_locked(self, st: Dict[str, Any], src_ip: str, sport: int, dst_ip: str, dport: int, info: Dict[str, Any]) -> None:
        version_name = info.get("version_name")
        if version_name == "IKEv2":
            if info.get("is_response"):
                if st.get("initiator") is None:
                    st["initiator"] = (dst_ip, int(dport))
                if st.get("responder") is None:
                    st["responder"] = (src_ip, int(sport))
                st["is_response_seen"] = True
            else:
                if st.get("initiator") is None:
                    st["initiator"] = (src_ip, int(sport))
                if st.get("responder") is None:
                    st["responder"] = (dst_ip, int(dport))
        else:
            if st.get("initiator") is None:
                st["initiator"] = (src_ip, int(sport))
            if st.get("responder") is None:
                st["responder"] = (dst_ip, int(dport))

    def _update_retransmit_locked(self, st: Dict[str, Any], info: Dict[str, Any]) -> None:
        msgid = info.get("msgid")
        exch = info.get("exchange_name")
        prev_msgid = st.get("last_msgid")
        prev_summary = st.get("last_summary") or {}

        if prev_msgid is not None and msgid == prev_msgid:
            if exch == prev_summary.get("exchange_name") and info.get("flags") == prev_summary.get("flags"):
                self._metrics["retransmit_suspect"] += 1
                try:
                    anoms = list(info.get("anomalies") or [])
                    anoms.append("retransmit-suspect")
                    info["anomalies"] = self._dedup_preserve(anoms)
                except Exception:
                    pass

        st["last_msgid"] = msgid

    def _should_log_locked(self, st: Dict[str, Any], now: float) -> bool:
        last = float(st.get("last_log", 0.0) or 0.0)
        if (now - last) >= self.RL_INTERVAL_SEC:
            st["last_log"] = now
            return True
        return False

    def _clean_if_needed_locked(self, now: float) -> None:
        if now - self._last_gc < 60.0:
            return

        stale = [
            k for k, v in self._flows.items()
            if now - float(v.get("last", now) or now) > self.flow_ttl_sec
        ]
        for k in stale:
            self._flows.pop(k, None)

        if len(self._flows) > self.flow_soft_max:
            excess = len(self._flows) - self.flow_soft_max
            victims = sorted(
                self._flows.items(),
                key=lambda kv: float(kv[1].get("last", 0.0) or 0.0),
            )[:excess]
            for k, _ in victims:
                self._flows.pop(k, None)
            self._metrics["flow_cache_evictions"] += excess

        self._metrics["active_flows"] = len(self._flows)
        self._last_gc = now

    def _maybe_emit_summary(self, now: float) -> None:
        if (now - self._last_summary) < self._summary_every:
            return
        self._last_summary = now
        self._emit_hook("summary", self.snapshot_metrics())

    # ------------------------------------------------------------------
    # Logging helpers
    # ------------------------------------------------------------------
    def _log_ike(self, src_ip: str, sport: int, dst_ip: str, dport: int, iface: str, info: Dict[str, Any]) -> None:
        bits: List[str] = []
        bits.append(info.get("version_name") or "IKE")
        bits.append(info.get("exchange_name") or f"exchange={info.get('exchange')}")
        bits.append(f"msgid={info.get('msgid')}")
        bits.append(f"flags={info.get('flags_text') or hex(int(info.get('flags', 0) or 0))}")
        bits.append(f"next={info.get('next_payload_name') or info.get('next_payload')}")
        bits.append(f"i_spi={self._short_spi(info.get('i_spi'))}")
        bits.append(f"r_spi={self._short_spi(info.get('r_spi'))}")
        if info.get("nat_t"):
            bits.append("NAT-T")
        if info.get("payload_names"):
            bits.append("payloads=" + ",".join(info.get("payload_names") or []))
        if info.get("notify_names"):
            bits.append("notify=" + ",".join(info.get("notify_names") or []))
        if info.get("partial"):
            bits.append("partial")
        if info.get("anomalies"):
            bits.append("anom=" + ",".join(info.get("anomalies") or []))

        self._safe_log(
            f"[Transport][🚀 UDP][🔐 IKE] {src_ip}:{sport} → {dst_ip}:{dport} on {iface} | " + " ".join(bits)
        )

    def _safe_log(self, msg: str) -> None:
        try:
            self.logger.log_message(msg)
        except Exception:
            try:
                self.logger(msg)
            except Exception:
                pass

    def _emit_hook(self, name: str, payload: dict) -> None:
        try:
            fn = self._hooks.get(name)
            if fn:
                fn(payload)
        except Exception:
            pass

    # ------------------------------------------------------------------
    # Byte extraction / classification helpers
    # ------------------------------------------------------------------
    def _extract_udp_payload(self, packet) -> Optional[bytes]:
        if packet is None:
            return None

        if isinstance(packet, (bytes, bytearray, memoryview)):
            try:
                raw = bytes(packet)
                return raw[: self.peek_cap] if raw else b""
            except Exception:
                return None

        try:
            if UDP is not None and hasattr(packet, "haslayer") and packet.haslayer(UDP):
                raw = bytes(packet[UDP].payload)
                return raw[: self.peek_cap] if raw else b""
        except Exception:
            pass

        try:
            if Raw is not None and hasattr(packet, "haslayer") and packet.haslayer(Raw):
                raw = bytes(packet[Raw].load)
                return raw[: self.peek_cap] if raw else b""
        except Exception:
            pass

        return None

    def _quick_ike_signature(self, payload: bytes) -> bool:
        raw = bytes(payload[: max(self.IKE_HDR_LEN + 4, 64)])
        if len(raw) < self.IKE_HDR_LEN:
            return False

        offsets = [0]
        if len(raw) >= self.IKE_HDR_LEN + 4 and raw[:4] == b"\x00\x00\x00\x00":
            offsets.insert(0, 4)

        for off in offsets:
            if len(raw) < off + self.IKE_HDR_LEN:
                continue
            ver = raw[off + 17]
            major = (ver >> 4) & 0x0F
            total_len = int.from_bytes(raw[off + 24: off + 28], "big", signed=False)
            if major in (1, 2) and total_len >= self.IKE_HDR_LEN:
                return True
        return False

    @staticmethod
    def _safe_port(value) -> Optional[int]:
        try:
            port = int(value)
            if 0 <= port <= 65535:
                return port
        except Exception:
            pass
        return None

    @staticmethod
    def _port_hit(port: int, ports: Tuple[int, int]) -> bool:
        return int(ports[0]) == int(port) or int(ports[1]) == int(port)

    def _flow_key(self, src_ip: str, sport: int, dst_ip: str, dport: int) -> Tuple[str, str, str, str]:
        a = (str(src_ip), str(int(sport)))
        b = (str(dst_ip), str(int(dport)))
        first, second = (a, b) if a <= b else (b, a)
        return first + second

    @staticmethod
    def _iface_suffix(inbound_iface) -> str:
        try:
            s = str(inbound_iface or "")
            return s.split("_")[-1] if "_" in s else s
        except Exception:
            return str(inbound_iface or "")

    def _exchange_name(self, version_name: str, exch: int) -> str:
        if version_name == "IKEv2":
            return self.IKEV2_EXCHANGE_NAMES.get(int(exch), f"EXCH({int(exch)})")
        return self.IKEV1_EXCHANGE_NAMES.get(int(exch), f"EXCH({int(exch)})")

    def _payload_name(self, version_name: str, payload_id: int) -> str:
        if version_name == "IKEv2":
            return self.IKEV2_PAYLOAD_NAMES.get(int(payload_id), f"Payload({int(payload_id)})")
        return self.IKEV1_PAYLOAD_NAMES.get(int(payload_id), f"Payload({int(payload_id)})")

    def _flags_text(self, version_name: str, flags: int) -> str:
        names: List[str] = []
        if version_name == "IKEv2":
            if flags & 0x08:
                names.append("initiator")
            if flags & 0x10:
                names.append("higher-ver")
            if flags & 0x20:
                names.append("response")
            unknown = flags & ~(0x08 | 0x10 | 0x20)
            if unknown:
                names.append(f"0x{unknown:02x}")
        else:
            if flags & 0x01:
                names.append("encrypted")
            if flags & 0x02:
                names.append("commit")
            if flags & 0x04:
                names.append("auth-only")
            unknown = flags & ~(0x01 | 0x02 | 0x04)
            if unknown:
                names.append(f"0x{unknown:02x}")
        return ",".join(names) if names else "0"

    @staticmethod
    def _short_spi(spi_hex: Optional[str]) -> str:
        s = str(spi_hex or "")
        if not s:
            return "-"
        if len(s) <= 16:
            return s
        return s[:8] + "…" + s[-4:]

    @staticmethod
    def _dedup_preserve(items: List[Any]) -> List[Any]:
        seen = set()
        out = []
        for item in items:
            if item is None:
                continue
            key = item if isinstance(item, (str, int, float, bytes, tuple)) else repr(item)
            if key in seen:
                continue
            seen.add(key)
            out.append(item)
        return out

class TransportSNMPManager:
        """
        SNMP transport observer for TransportManager.

        Watches:
          - UDP/161  SNMP agent requests/responses
          - UDP/162  SNMP traps/informs
          - TCP/161  rare SNMP-over-TCP
          - TCP/162  rare trap/inform-over-TCP
          - TCP/UDP 10161/10162 secure SNMP ports are classified but not decoded

        Public API:
          - handle(packet, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool
          - handle_udp(packet, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool
          - snapshot_metrics() -> dict
        """

        # -------------------------
        # Tunables
        # -------------------------
        FLOW_TTL_SEC = 10 * 60
        FLOW_SOFT_MAX = 20_000
        RL_INTERVAL_SEC = 1.0
        BYTES_BUDGET = 4096

        PORT_SNMP = 161
        PORT_SNMP_TRAP = 162

        # SNMP over TLS/DTLS ports. These are usually encrypted, so this manager
        # logs them as SNMP-secure transport hints instead of trying to BER-parse them.
        PORT_SNMP_TLS = 10161
        PORT_SNMP_TLS_TRAP = 10162

        DETECT_OFFPORT_SNMP = False
        MAX_VARBINDS_LOG = 8
        MAX_OID_TEXT = 96
        MAX_VALUE_TEXT = 120
        REDACT_COMMUNITY = True

        PDU_TYPES = {
            0xA0: "GetRequest",
            0xA1: "GetNextRequest",
            0xA2: "Response",
            0xA3: "SetRequest",
            0xA4: "TrapV1",
            0xA5: "GetBulkRequest",
            0xA6: "InformRequest",
            0xA7: "TrapV2",
            0xA8: "Report",
        }

        VERSION_NAMES = {
            0: "v1",
            1: "v2c",
            3: "v3",
        }

        ERROR_STATUS = {
            0: "noError",
            1: "tooBig",
            2: "noSuchName",
            3: "badValue",
            4: "readOnly",
            5: "genErr",
            6: "noAccess",
            7: "wrongType",
            8: "wrongLength",
            9: "wrongEncoding",
            10: "wrongValue",
            11: "noCreation",
            12: "inconsistentValue",
            13: "resourceUnavailable",
            14: "commitFailed",
            15: "undoFailed",
            16: "authorizationError",
            17: "notWritable",
            18: "inconsistentName",
        }

        COMMON_OIDS = {
            "1.3.6.1.2.1.1.1": "sysDescr",
            "1.3.6.1.2.1.1.2": "sysObjectID",
            "1.3.6.1.2.1.1.3": "sysUpTime",
            "1.3.6.1.2.1.1.4": "sysContact",
            "1.3.6.1.2.1.1.5": "sysName",
            "1.3.6.1.2.1.1.6": "sysLocation",
            "1.3.6.1.2.1.2.2.1.1": "ifIndex",
            "1.3.6.1.2.1.2.2.1.2": "ifDescr",
            "1.3.6.1.2.1.2.2.1.3": "ifType",
            "1.3.6.1.2.1.2.2.1.4": "ifMtu",
            "1.3.6.1.2.1.2.2.1.5": "ifSpeed",
            "1.3.6.1.2.1.2.2.1.6": "ifPhysAddress",
            "1.3.6.1.2.1.2.2.1.7": "ifAdminStatus",
            "1.3.6.1.2.1.2.2.1.8": "ifOperStatus",
            "1.3.6.1.2.1.2.2.1.10": "ifInOctets",
            "1.3.6.1.2.1.2.2.1.16": "ifOutOctets",
            "1.3.6.1.6.3.1.1.4.1": "snmpTrapOID",
            "1.3.6.1.6.3.1.1.4.3": "snmpTrapEnterprise",
            "1.3.6.1.2.1.25": "hostResources",
            "1.3.6.1.4.1": "enterprise",
        }

        def __init__(self, logger):
            self.logger = logger
            self._peek_cap = int(self.BYTES_BUDGET)
            self.logging_enabled = True
            self.flow_cache_ttl = int(self.FLOW_TTL_SEC)
            self.flow_cache_max = int(self.FLOW_SOFT_MAX)

            self._lock = threading.RLock()
            self._flows: Dict[Tuple[str, str, str, str, str], Dict[str, Any]] = {}

            self._metrics = {
                "seen_tcp": 0,
                "seen_udp": 0,
                "matched_tcp": 0,
                "matched_udp": 0,
                "v1": 0,
                "v2c": 0,
                "v3": 0,
                "secure_transport": 0,
                "get": 0,
                "getnext": 0,
                "getbulk": 0,
                "set": 0,
                "response": 0,
                "trap": 0,
                "inform": 0,
                "report": 0,
                "malformed": 0,
                "errors": 0,
                "flow_cache_evictions": 0,
                "active_flows": 0,
            }

            self._safe_log("[Transport][📡 SNMP] Manager ready")

        # ------------------------------------------------------------------
        # Public entrypoints
        # ------------------------------------------------------------------

        def handle(self, packet, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool:
            """TCP SNMP observer. SNMP is usually UDP, but TCP/161 exists."""
            try:
                sport_i = self._safe_port(sport)
                dport_i = self._safe_port(dport)
                if sport_i is None or dport_i is None:
                    return False

                if not self._is_snmp_port(sport_i, dport_i) and not self.DETECT_OFFPORT_SNMP:
                    return False

                payload = self._extract_payload(packet, want_udp=False)
                if payload is None:
                    return False

                now = time.time()
                key = self._flow_key(src_ip, sport_i, dst_ip, dport_i, "tcp")
                st = self._touch_flow_locked(key, now)

                with self._lock:
                    self._metrics["seen_tcp"] += 1

                handled, info = self._classify_payload(payload, sport_i, dport_i, proto="tcp")
                if not handled:
                    return False

                with self._lock:
                    self._metrics["matched_tcp"] += 1
                    self._bump_metrics_from_info(info)
                    do_log = self._should_log_locked(st, now)
                    self._clean_if_needed_locked(now)

                if do_log:
                    self._log_line("TCP", src_ip, sport_i, dst_ip, dport_i, inbound_iface, info)

                return True

            except Exception:
                with self._lock:
                    self._metrics["errors"] += 1
                return False

        def handle_udp(self, packet, src_ip, dst_ip, sport, dport, inbound_iface=None) -> bool:
            """UDP SNMP observer."""
            try:
                sport_i = self._safe_port(sport)
                dport_i = self._safe_port(dport)
                if sport_i is None or dport_i is None:
                    return False

                if not self._is_snmp_port(sport_i, dport_i) and not self.DETECT_OFFPORT_SNMP:
                    return False

                payload = self._extract_payload(packet, want_udp=True)
                if payload is None:
                    return False

                now = time.time()
                key = self._flow_key(src_ip, sport_i, dst_ip, dport_i, "udp")
                st = self._touch_flow_locked(key, now)

                with self._lock:
                    self._metrics["seen_udp"] += 1

                handled, info = self._classify_payload(payload, sport_i, dport_i, proto="udp")
                if not handled:
                    return False

                with self._lock:
                    self._metrics["matched_udp"] += 1
                    self._bump_metrics_from_info(info)
                    do_log = self._should_log_locked(st, now)
                    self._clean_if_needed_locked(now)

                if do_log:
                    self._log_line("UDP", src_ip, sport_i, dst_ip, dport_i, inbound_iface, info)

                return True

            except Exception:
                with self._lock:
                    self._metrics["errors"] += 1
                return False

        def snapshot_metrics(self) -> dict:
            with self._lock:
                out = dict(self._metrics)
                out["active_flows"] = len(self._flows)
                return out

        # ------------------------------------------------------------------
        # Classification
        # ------------------------------------------------------------------

        def _classify_payload(self, raw: bytes, sport: int, dport: int, proto: str) -> Tuple[bool, Dict[str, Any]]:
            if self._is_snmp_secure_port(sport, dport):
                return True, {
                    "kind": "snmp-secure",
                    "version": "-",
                    "version_name": "secure",
                    "pdu": "encrypted-or-dtls",
                    "direction": self._direction_from_ports(sport, dport),
                    "flags": "secure-port,no-ber-decode",
                    "varbinds": [],
                }

            if not raw:
                return True, {
                    "kind": "snmp-empty",
                    "version": "-",
                    "version_name": "-",
                    "pdu": "empty",
                    "direction": self._direction_from_ports(sport, dport),
                    "flags": "empty-payload",
                    "varbinds": [],
                }

            parsed = self._parse_snmp_message(raw)
            if not parsed.get("ok"):
                if self._is_snmp_port(sport, dport):
                    with self._lock:
                        self._metrics["malformed"] += 1
                    return True, {
                        "kind": "snmp-malformed",
                        "version": "?",
                        "version_name": "?",
                        "pdu": "malformed",
                        "direction": self._direction_from_ports(sport, dport),
                        "flags": parsed.get("reason", "parse-failed"),
                        "varbinds": [],
                        "payload_len": len(raw),
                    }
                return False, {}

            info = parsed["info"]
            info["direction"] = self._direction_from_ports(sport, dport)
            info["payload_len"] = len(raw)

            flags = []
            if dport == self.PORT_SNMP:
                flags.append("agent-port")
            elif sport == self.PORT_SNMP:
                flags.append("agent-response")
            if dport == self.PORT_SNMP_TRAP:
                flags.append("trap-port")
            elif sport == self.PORT_SNMP_TRAP:
                flags.append("trap-source")

            if proto == "tcp":
                flags.append("tcp-snmp")
            else:
                flags.append("udp-snmp")

            if info.get("truncated"):
                flags.append("truncated-log")

            info["flags"] = self._join_flags(info.get("flags"), ",".join(flags))
            return True, info

        # ------------------------------------------------------------------
        # SNMP BER parser
        # ------------------------------------------------------------------

        def _parse_snmp_message(self, raw: bytes) -> Dict[str, Any]:
            """
            Minimal SNMP BER parser.

            Supports:
              - v1/v2c top-level: SEQUENCE -> version, community, PDU
              - v3 top-level: SEQUENCE -> version, headerData, securityParams, scopedPDU/encryptedPDU
            """
            try:
                top = self._read_tlv(raw, 0, len(raw))
                if not top:
                    return {"ok": False, "reason": "no-top-tlv"}

                if top["tag"] != 0x30:
                    return {"ok": False, "reason": f"top-tag-0x{top['tag']:02x}-not-sequence"}

                children = self._read_children(top["value"], max_children=8)
                if len(children) < 2:
                    return {"ok": False, "reason": "short-message"}

                version_tlv = children[0]
                if version_tlv["tag"] != 0x02:
                    return {"ok": False, "reason": "missing-version-int"}

                version = self._ber_int(version_tlv["value"])
                version_name = self.VERSION_NAMES.get(version, f"v{version}")

                if version in (0, 1):
                    return self._parse_v1_v2c(version, version_name, children)

                if version == 3:
                    return self._parse_v3(version, version_name, children)

                return {
                    "ok": True,
                    "info": {
                        "kind": "snmp",
                        "version": version,
                        "version_name": version_name,
                        "community": "-",
                        "pdu": "unknown-version",
                        "request_id": None,
                        "varbinds": [],
                        "flags": "unknown-version",
                    },
                }

            except Exception as e:
                return {"ok": False, "reason": f"exception:{type(e).__name__}"}

        def _parse_v1_v2c(self, version: int, version_name: str, children: List[Dict[str, Any]]) -> Dict[str, Any]:
            if len(children) < 3:
                return {"ok": False, "reason": "short-v1-v2c-message"}

            community_tlv = children[1]
            if community_tlv["tag"] != 0x04:
                return {"ok": False, "reason": "missing-community"}

            community_raw = community_tlv["value"]
            community = self._render_community(community_raw)

            pdu_tlv = children[2]
            if pdu_tlv["tag"] not in self.PDU_TYPES:
                return {"ok": False, "reason": f"unknown-pdu-tag-0x{pdu_tlv['tag']:02x}"}

            pdu_info = self._parse_pdu(pdu_tlv)

            return {
                "ok": True,
                "info": {
                    "kind": "snmp",
                    "version": version,
                    "version_name": version_name,
                    "community": community,
                    **pdu_info,
                },
            }

        def _parse_v3(self, version: int, version_name: str, children: List[Dict[str, Any]]) -> Dict[str, Any]:
            info: Dict[str, Any] = {
                "kind": "snmp",
                "version": version,
                "version_name": version_name,
                "community": "-",
                "pdu": "v3",
                "request_id": None,
                "varbinds": [],
                "flags": "v3",
            }

            # SNMPv3 layout:
            # version, headerData, securityParameters, data
            if len(children) < 4:
                info["flags"] = self._join_flags(info.get("flags"), "short-v3")
                return {"ok": True, "info": info}

            header_tlv = children[1]
            security_tlv = children[2]
            data_tlv = children[3]

            if header_tlv["tag"] == 0x30:
                header = self._read_children(header_tlv["value"], max_children=6)
                if len(header) >= 4:
                    info["msg_id"] = self._ber_int(header[0]["value"]) if header[0]["tag"] == 0x02 else None
                    info["max_size"] = self._ber_int(header[1]["value"]) if header[1]["tag"] == 0x02 else None
                    info["msg_flags"] = self._render_octets(header[2]["value"], maxlen=16) if header[2][
                                                                                                  "tag"] == 0x04 else None
                    info["sec_model"] = self._ber_int(header[3]["value"]) if header[3]["tag"] == 0x02 else None

            if security_tlv["tag"] == 0x04:
                usm = self._parse_v3_usm_security_parameters(security_tlv["value"])
                if usm:
                    info.update(usm)

            # Encrypted scopedPDU is usually OCTET STRING.
            if data_tlv["tag"] == 0x04:
                info["pdu"] = "encrypted-scopedPDU"
                info["flags"] = self._join_flags(info.get("flags"), "privacy/encrypted")
                return {"ok": True, "info": info}

            # Plaintext scopedPDU is SEQUENCE: contextEngineID, contextName, PDU
            if data_tlv["tag"] == 0x30:
                scoped = self._read_children(data_tlv["value"], max_children=6)
                if len(scoped) >= 3:
                    if scoped[1]["tag"] == 0x04:
                        info["context"] = self._safe_text(scoped[1]["value"], 64) or "-"
                    pdu_tlv = scoped[2]
                    if pdu_tlv["tag"] in self.PDU_TYPES:
                        pdu_info = self._parse_pdu(pdu_tlv)
                        info.update(pdu_info)
                        info["flags"] = self._join_flags(info.get("flags"), "plaintext-scopedPDU")
                        return {"ok": True, "info": info}

            # Fallback: recursively hunt a PDU tag in the v3 data area.
            found = self._find_first_pdu_tlv(data_tlv)
            if found:
                pdu_info = self._parse_pdu(found)
                info.update(pdu_info)
                info["flags"] = self._join_flags(info.get("flags"), "pdu-found-recursive")
                return {"ok": True, "info": info}

            info["flags"] = self._join_flags(info.get("flags"), f"data-tag-0x{data_tlv['tag']:02x}")
            return {"ok": True, "info": info}

        def _parse_pdu(self, pdu_tlv: Dict[str, Any]) -> Dict[str, Any]:
            pdu_tag = int(pdu_tlv["tag"])
            pdu_name = self.PDU_TYPES.get(pdu_tag, f"PDU-0x{pdu_tag:02x}")

            if pdu_tag == 0xA4:
                return self._parse_v1_trap_pdu(pdu_tlv)

            children = self._read_children(pdu_tlv["value"], max_children=8)

            request_id = None
            error_status = None
            error_index = None
            non_repeaters = None
            max_repetitions = None
            varbinds: List[Dict[str, Any]] = []

            if len(children) >= 1 and children[0]["tag"] == 0x02:
                request_id = self._ber_int(children[0]["value"])

            if pdu_tag == 0xA5:
                # GetBulk: request-id, non-repeaters, max-repetitions, varbind-list
                if len(children) >= 2 and children[1]["tag"] == 0x02:
                    non_repeaters = self._ber_int(children[1]["value"])
                if len(children) >= 3 and children[2]["tag"] == 0x02:
                    max_repetitions = self._ber_int(children[2]["value"])
                if len(children) >= 4 and children[3]["tag"] == 0x30:
                    varbinds = self._parse_varbind_list(children[3])
            else:
                # Standard PDU: request-id, error-status, error-index, varbind-list
                if len(children) >= 2 and children[1]["tag"] == 0x02:
                    error_status = self._ber_int(children[1]["value"])
                if len(children) >= 3 and children[2]["tag"] == 0x02:
                    error_index = self._ber_int(children[2]["value"])
                if len(children) >= 4 and children[3]["tag"] == 0x30:
                    varbinds = self._parse_varbind_list(children[3])

            flags = []
            if error_status not in (None, 0):
                flags.append(f"error={self.ERROR_STATUS.get(error_status, error_status)}")
            if len(varbinds) >= self.MAX_VARBINDS_LOG:
                flags.append("varbind-log-capped")

            out = {
                "pdu": pdu_name,
                "request_id": request_id,
                "error_status": error_status,
                "error_index": error_index,
                "varbinds": varbinds[: self.MAX_VARBINDS_LOG],
                "truncated": len(varbinds) > self.MAX_VARBINDS_LOG,
                "flags": ",".join(flags) if flags else None,
            }

            if non_repeaters is not None:
                out["non_repeaters"] = non_repeaters
            if max_repetitions is not None:
                out["max_repetitions"] = max_repetitions

            return out

        def _parse_v1_trap_pdu(self, pdu_tlv: Dict[str, Any]) -> Dict[str, Any]:
            children = self._read_children(pdu_tlv["value"], max_children=12)

            enterprise = None
            agent_addr = None
            generic_trap = None
            specific_trap = None
            uptime = None
            varbinds: List[Dict[str, Any]] = []

            if len(children) >= 1 and children[0]["tag"] == 0x06:
                enterprise = self._decode_oid(children[0]["value"])
            if len(children) >= 2 and children[1]["tag"] == 0x40:
                agent_addr = self._decode_ipaddress(children[1]["value"])
            if len(children) >= 3 and children[2]["tag"] == 0x02:
                generic_trap = self._ber_int(children[2]["value"])
            if len(children) >= 4 and children[3]["tag"] == 0x02:
                specific_trap = self._ber_int(children[3]["value"])
            if len(children) >= 5 and children[4]["tag"] == 0x43:
                uptime = self._ber_uint(children[4]["value"])
            if len(children) >= 6 and children[5]["tag"] == 0x30:
                varbinds = self._parse_varbind_list(children[5])

            return {
                "pdu": "TrapV1",
                "request_id": None,
                "enterprise": self._name_oid(enterprise) if enterprise else None,
                "agent_addr": agent_addr,
                "generic_trap": generic_trap,
                "specific_trap": specific_trap,
                "uptime": uptime,
                "varbinds": varbinds[: self.MAX_VARBINDS_LOG],
                "truncated": len(varbinds) > self.MAX_VARBINDS_LOG,
                "flags": "v1-trap",
            }

        def _parse_varbind_list(self, seq_tlv: Dict[str, Any]) -> List[Dict[str, Any]]:
            out: List[Dict[str, Any]] = []
            vb_tlvs = self._read_children(seq_tlv["value"], max_children=64)

            for vb in vb_tlvs:
                if vb["tag"] != 0x30:
                    continue

                parts = self._read_children(vb["value"], max_children=4)
                if len(parts) < 2:
                    continue

                oid_tlv = parts[0]
                val_tlv = parts[1]

                if oid_tlv["tag"] != 0x06:
                    continue

                oid = self._decode_oid(oid_tlv["value"])
                value = self._render_value_tlv(val_tlv)

                out.append({
                    "oid": self._name_oid(oid),
                    "raw_oid": oid,
                    "value": value,
                    "tag": f"0x{val_tlv['tag']:02x}",
                })

            return out

        def _parse_v3_usm_security_parameters(self, raw: bytes) -> Dict[str, Any]:
            """
            USM securityParameters is an OCTET STRING containing encoded BER.
            This safely parses common fields when present:
              engineID, boots, time, username, authParams, privParams
            """
            try:
                top = self._read_tlv(raw, 0, len(raw))
                if not top or top["tag"] != 0x30:
                    return {}

                children = self._read_children(top["value"], max_children=8)
                out: Dict[str, Any] = {}

                if len(children) >= 4:
                    if children[3]["tag"] == 0x04:
                        user = self._safe_text(children[3]["value"], 64)
                        if user:
                            out["user"] = user

                if len(children) >= 2 and children[1]["tag"] == 0x02:
                    out["engine_boots"] = self._ber_int(children[1]["value"])

                if len(children) >= 3 and children[2]["tag"] == 0x02:
                    out["engine_time"] = self._ber_int(children[2]["value"])

                return out

            except Exception:
                return {}

        def _find_first_pdu_tlv(self, tlv: Dict[str, Any], depth: int = 0) -> Optional[Dict[str, Any]]:
            if depth > 4:
                return None

            if tlv["tag"] in self.PDU_TYPES:
                return tlv

            if tlv["tag"] not in (0x30,):
                return None

            for child in self._read_children(tlv["value"], max_children=16):
                found = self._find_first_pdu_tlv(child, depth + 1)
                if found:
                    return found

            return None

        # ------------------------------------------------------------------
        # BER helpers
        # ------------------------------------------------------------------

        def _read_tlv(self, buf: bytes, off: int, end: int) -> Optional[Dict[str, Any]]:
            if off < 0 or off >= end or off >= len(buf):
                return None

            start = off
            tag = buf[off]
            off += 1

            if off >= end or off >= len(buf):
                return None

            first_len = buf[off]
            off += 1

            if first_len & 0x80:
                n = first_len & 0x7F
                if n == 0:
                    return None
                if n > 4:
                    return None
                if off + n > end or off + n > len(buf):
                    return None
                length = int.from_bytes(buf[off:off + n], "big", signed=False)
                off += n
            else:
                length = first_len

            val_start = off
            val_end = off + length
            if val_end > end or val_end > len(buf):
                return None

            return {
                "tag": tag,
                "start": start,
                "value_start": val_start,
                "end": val_end,
                "length": length,
                "value": buf[val_start:val_end],
            }

        def _read_children(self, value: bytes, max_children: int = 32) -> List[Dict[str, Any]]:
            out: List[Dict[str, Any]] = []
            off = 0
            end = len(value)

            while off < end and len(out) < max_children:
                tlv = self._read_tlv(value, off, end)
                if not tlv:
                    break
                out.append(tlv)
                if tlv["end"] <= off:
                    break
                off = tlv["end"]

            return out

        @staticmethod
        def _ber_int(value: bytes) -> int:
            if not value:
                return 0
            return int.from_bytes(value, "big", signed=bool(value[0] & 0x80))

        @staticmethod
        def _ber_uint(value: bytes) -> int:
            if not value:
                return 0
            return int.from_bytes(value, "big", signed=False)

        def _decode_oid(self, value: bytes) -> str:
            if not value:
                return ""

            nums: List[int] = []
            first = value[0]
            if first < 40:
                nums.extend([0, first])
            elif first < 80:
                nums.extend([1, first - 40])
            else:
                nums.extend([2, first - 80])

            n = 0
            for b in value[1:]:
                n = (n << 7) | (b & 0x7F)
                if not (b & 0x80):
                    nums.append(n)
                    n = 0

            if n:
                nums.append(n)

            return ".".join(str(x) for x in nums)

        def _name_oid(self, oid: Optional[str]) -> str:
            if not oid:
                return "-"

            oid = str(oid)
            best_name = None
            best_prefix = ""

            for prefix, name in self.COMMON_OIDS.items():
                if oid == prefix or oid.startswith(prefix + "."):
                    if len(prefix) > len(best_prefix):
                        best_prefix = prefix
                        best_name = name

            if best_name:
                suffix = oid[len(best_prefix):].lstrip(".")
                named = f"{best_name}.{suffix}" if suffix else best_name
            else:
                named = oid

            if len(named) > self.MAX_OID_TEXT:
                named = named[: self.MAX_OID_TEXT] + "…"

            return named

        def _render_value_tlv(self, tlv: Dict[str, Any]) -> str:
            tag = int(tlv["tag"])
            val = tlv["value"]

            try:
                if tag == 0x05:
                    return "NULL"
                if tag == 0x02:
                    return str(self._ber_int(val))
                if tag == 0x06:
                    return self._name_oid(self._decode_oid(val))
                if tag == 0x04:
                    return self._render_octets(val, self.MAX_VALUE_TEXT)
                if tag == 0x40:
                    return self._decode_ipaddress(val)
                if tag == 0x41:
                    return f"Counter32={self._ber_uint(val)}"
                if tag == 0x42:
                    return f"Gauge32={self._ber_uint(val)}"
                if tag == 0x43:
                    return f"TimeTicks={self._ber_uint(val)}"
                if tag == 0x44:
                    return f"Opaque[{len(val)}]"
                if tag == 0x46:
                    return f"Counter64={self._ber_uint(val)}"
                if tag == 0x80:
                    return "noSuchObject"
                if tag == 0x81:
                    return "noSuchInstance"
                if tag == 0x82:
                    return "endOfMibView"
                return f"tag=0x{tag:02x}[{len(val)}B]"
            except Exception:
                return f"tag=0x{tag:02x}[decode-error]"

        def _render_octets(self, raw: bytes, maxlen: int = 64) -> str:
            if raw is None:
                return "-"

            if not raw:
                return '""'

            printable = True
            for b in raw:
                if b in (9, 10, 13):
                    continue
                if b < 32 or b > 126:
                    printable = False
                    break

            if printable:
                s = raw.decode("utf-8", "ignore").replace("\r", "\\r").replace("\n", "\\n")
                if len(s) > maxlen:
                    s = s[:maxlen] + "…"
                return f'"{s}"'

            hx = raw[: max(1, maxlen // 2)].hex()
            if len(raw) > max(1, maxlen // 2):
                hx += "…"
            return f"hex:{hx}"

        def _render_community(self, raw: bytes) -> str:
            if not self.REDACT_COMMUNITY:
                return self._safe_text(raw, 64) or "-"

            try:
                import hashlib
                digest = hashlib.sha1(raw or b"").hexdigest()[:10]
                return f"redacted(len={len(raw)},sha1={digest})"
            except Exception:
                return f"redacted(len={len(raw)})"

        def _decode_ipaddress(self, raw: bytes) -> str:
            if len(raw) == 4:
                return ".".join(str(b) for b in raw)
            return self._render_octets(raw, 32)

        def _safe_text(self, raw: bytes, maxlen: int = 64) -> Optional[str]:
            if raw is None:
                return None
            try:
                s = raw.decode("utf-8", "ignore")
                s = "".join(ch for ch in s if ch >= " " or ch == "\t").strip()
                if not s:
                    return None
                if len(s) > maxlen:
                    s = s[:maxlen] + "…"
                return s
            except Exception:
                return None

        # ------------------------------------------------------------------
        # Logging
        # ------------------------------------------------------------------

        def _log_line(self, proto_label: str, sip, sport, dip, dport, iface, info: Dict[str, Any]) -> None:
            arrow = "→"
            icon = "🚀 UDP" if proto_label.upper() == "UDP" else "🧵 TCP"
            iface_s = self._iface_suffix(iface)

            version = info.get("version_name", "?")
            pdu = info.get("pdu", "?")
            direction = info.get("direction", "?")
            request_id = info.get("request_id")
            community = info.get("community")
            flags = info.get("flags") or "-"
            payload_len = info.get("payload_len")

            bits = [
                f"[Transport][{icon}][📡 SNMP]",
                f"{version}",
                f"{pdu}",
                f"{sip}:{sport} {arrow} {dip}:{dport}",
                f"on {iface_s}",
                f"| dir={direction}",
            ]

            if request_id is not None:
                bits.append(f"req={request_id}")

            if community and community != "-":
                bits.append(f"community={community}")

            if info.get("user"):
                bits.append(f"user={info.get('user')}")

            if info.get("context"):
                bits.append(f"context={info.get('context')}")

            if info.get("msg_id") is not None:
                bits.append(f"msgid={info.get('msg_id')}")

            if info.get("error_status") not in (None, 0):
                es = info.get("error_status")
                bits.append(f"error={self.ERROR_STATUS.get(es, es)}")

            if info.get("non_repeaters") is not None:
                bits.append(f"nonrep={info.get('non_repeaters')}")

            if info.get("max_repetitions") is not None:
                bits.append(f"maxrep={info.get('max_repetitions')}")

            if info.get("enterprise"):
                bits.append(f"enterprise={info.get('enterprise')}")

            if info.get("agent_addr"):
                bits.append(f"agent={info.get('agent_addr')}")

            if info.get("uptime") is not None:
                bits.append(f"uptime={info.get('uptime')}")

            varbinds = info.get("varbinds") or []
            if varbinds:
                vb_text = self._format_varbinds(varbinds)
                bits.append(f"varbinds={vb_text}")

            if payload_len is not None:
                bits.append(f"bytes={payload_len}")

            bits.append(f"flags={flags}")

            self._safe_log(" ".join(str(x) for x in bits if x is not None))

        def _format_varbinds(self, varbinds: List[Dict[str, Any]]) -> str:
            out = []
            for vb in varbinds[: self.MAX_VARBINDS_LOG]:
                oid = vb.get("oid") or "-"
                val = vb.get("value") or "-"
                text = f"{oid}={val}"
                if len(text) > 180:
                    text = text[:180] + "…"
                out.append(text)
            return ";".join(out) if out else "-"

        # ------------------------------------------------------------------
        # Metrics / flow helpers
        # ------------------------------------------------------------------

        def _bump_metrics_from_info(self, info: Dict[str, Any]) -> None:
            version = info.get("version")
            pdu = str(info.get("pdu") or "").lower()

            if info.get("kind") == "snmp-secure":
                self._metrics["secure_transport"] += 1

            if version == 0:
                self._metrics["v1"] += 1
            elif version == 1:
                self._metrics["v2c"] += 1
            elif version == 3:
                self._metrics["v3"] += 1

            if "getbulk" in pdu:
                self._metrics["getbulk"] += 1
            elif "getnext" in pdu:
                self._metrics["getnext"] += 1
            elif "getrequest" in pdu:
                self._metrics["get"] += 1
            elif "setrequest" in pdu:
                self._metrics["set"] += 1
            elif "response" in pdu:
                self._metrics["response"] += 1
            elif "inform" in pdu:
                self._metrics["inform"] += 1
            elif "trap" in pdu:
                self._metrics["trap"] += 1
            elif "report" in pdu:
                self._metrics["report"] += 1

            self._metrics["active_flows"] = len(self._flows)

        def _touch_flow_locked(self, key, now: float) -> Dict[str, Any]:
            with self._lock:
                st = self._flows.get(key)
                if st is None:
                    st = {
                        "first": now,
                        "last": now,
                        "last_log": 0.0,
                        "hits": 0,
                    }
                    self._flows[key] = st
                st["last"] = now
                st["hits"] = int(st.get("hits", 0) or 0) + 1
                return st

        def _should_log_locked(self, st: Dict[str, Any], now: float) -> bool:
            last = float(st.get("last_log", 0.0) or 0.0)
            if (now - last) >= self.RL_INTERVAL_SEC:
                st["last_log"] = now
                return True
            return False

        def _clean_if_needed_locked(self, now_ts: float) -> None:
            total_seen = int(self._metrics.get("seen_tcp", 0) or 0) + int(self._metrics.get("seen_udp", 0) or 0)

            if total_seen > 0 and total_seen % 2048 == 0:
                ttl = int(self.flow_cache_ttl or 0)
                if ttl > 0:
                    stale = [
                        k for k, v in self._flows.items()
                        if (now_ts - float(v.get("last", now_ts) or now_ts)) > ttl
                    ]
                    for k in stale:
                        self._flows.pop(k, None)

            if len(self._flows) > self.flow_cache_max:
                excess = len(self._flows) - self.flow_cache_max
                victims = sorted(
                    self._flows.items(),
                    key=lambda kv: float(kv[1].get("last", 0.0) or 0.0)
                )[:excess]

                for k, _ in victims:
                    self._flows.pop(k, None)

                self._metrics["flow_cache_evictions"] += excess

            self._metrics["active_flows"] = len(self._flows)

        # ------------------------------------------------------------------
        # Packet helpers
        # ------------------------------------------------------------------

        def _extract_payload(self, pkt, *, want_udp: bool) -> Optional[bytes]:
            """
            Returns transport payload bytes.

            Accepts:
              - Scapy Packet
              - bytes / bytearray / memoryview payload
            """
            if pkt is None:
                return None

            if isinstance(pkt, (bytes, bytearray, memoryview)):
                try:
                    raw = bytes(pkt)
                    return raw[: self._peek_cap] if raw else b""
                except Exception:
                    return None

            layer = UDP if want_udp else TCP

            try:
                if layer is not None and hasattr(pkt, "haslayer") and pkt.haslayer(layer):
                    trans = pkt[layer]
                    if hasattr(trans, "payload"):
                        raw = bytes(trans.payload)
                        return raw[: self._peek_cap] if raw else b""
            except Exception:
                pass

            try:
                if Raw is not None and hasattr(pkt, "haslayer") and pkt.haslayer(Raw):
                    raw = bytes(pkt[Raw].load)
                    return raw[: self._peek_cap] if raw else b""
            except Exception:
                pass

            return None

        @staticmethod
        def _safe_port(port_val) -> Optional[int]:
            try:
                p = int(port_val)
                if 0 <= p <= 65535:
                    return p
                return None
            except Exception:
                return None

        def _is_snmp_port(self, sport: int, dport: int) -> bool:
            ports = (int(sport), int(dport))
            return (
                    self.PORT_SNMP in ports
                    or self.PORT_SNMP_TRAP in ports
                    or self.PORT_SNMP_TLS in ports
                    or self.PORT_SNMP_TLS_TRAP in ports
            )

        def _is_snmp_secure_port(self, sport: int, dport: int) -> bool:
            ports = (int(sport), int(dport))
            return self.PORT_SNMP_TLS in ports or self.PORT_SNMP_TLS_TRAP in ports

        def _direction_from_ports(self, sport: int, dport: int) -> str:
            sport = int(sport)
            dport = int(dport)

            if dport == self.PORT_SNMP:
                return "manager-to-agent"
            if sport == self.PORT_SNMP:
                return "agent-to-manager"
            if dport == self.PORT_SNMP_TRAP:
                return "agent-to-manager-trap"
            if sport == self.PORT_SNMP_TRAP:
                return "manager-to-agent-trap-reply"

            if dport == self.PORT_SNMP_TLS:
                return "manager-to-agent-secure"
            if sport == self.PORT_SNMP_TLS:
                return "agent-to-manager-secure"
            if dport == self.PORT_SNMP_TLS_TRAP:
                return "agent-to-manager-secure-trap"
            if sport == self.PORT_SNMP_TLS_TRAP:
                return "manager-to-agent-secure-trap-reply"

            return "unknown"

        def _flow_key(self, src_ip: str, sport: int, dst_ip: str, dport: int, proto: str):
            a = (str(src_ip), str(int(sport)))
            b = (str(dst_ip), str(int(dport)))
            first, second = (a, b) if a <= b else (b, a)
            return first + second + (str(proto),)

        def _iface_suffix(self, inbound_iface) -> str:
            try:
                s = str(inbound_iface or "")
                return s.split("_")[-1] if "_" in s else s
            except Exception:
                return str(inbound_iface or "")

        def _safe_log(self, msg: str) -> None:
            if not self.logging_enabled:
                return
            try:
                self.logger.log_message(msg)
            except Exception:
                try:
                    self.logger(msg)
                except Exception:
                    pass

        @staticmethod
        def _join_flags(*flags: Optional[str]) -> Optional[str]:
            flat: List[str] = []
            for item in flags:
                if not item:
                    continue
                parts = [p.strip() for p in str(item).split(",") if p.strip()]
                flat.extend(parts)

            seen = set()
            out: List[str] = []
            for p in flat:
                if p not in seen:
                    seen.add(p)
                    out.append(p)

            return ",".join(out) if out else None
class TransportManager:
    """
    Safer TransportManager for Hyper-V / WinDivert / WinTun environments.

    Main safety changes:
      - never pass live Scapy Packet objects into ParallelPython
      - freeze inbound packets to immutable bytes immediately
      - main TCP/UDP dispatch runs locally on the caller thread
      - only optional analysis wrappers use ParallelPython, and they receive bytes
      - serialize main dispatch paths to reduce cross-thread packet-writer races
    """

    def __init__(self, router_logger, packet_signer, code_output_manager, parallel_python, packet_writer):
        self.logger = router_logger
        self.parallel_python = parallel_python
        self.code_output_manager = code_output_manager
        self.sniffer = None
        self.packet_signer = packet_signer
        self.packet_writer = packet_writer

        self.logger.log_message("[Transport] Manager initialized (safe Hyper-V mode).")

        self.voip_port_range = range(10000, 20001)
        self.logged_quic_streams = {}
        self.QUIC_STREAM_TIMEOUT = 300
        self.last_quic_cleanup_time = time.time()

        # Safety controls
        self._dispatch_lock = threading.RLock()
        self._tls_lock = threading.RLock()
        self._analysis_parallel_enabled = hasattr(self.parallel_python, "run_parallel")

        # TLS record manager + callbacks
        self.tls_manager = TLSRecordManager(self.logger)
        self._wire_tls_callbacks()

        # Minimal initiator tracker to set c2s/s2c directions reliably
        self._initiators: Dict[Tuple[Tuple[str, int], Tuple[str, int]], Tuple[str, int]] = {}

        self.TLS_ALERT_LEVEL = {1: "warning", 2: "fatal"}
        self.TLS_ALERT_DESCRIPTION = {
            0: "close_notify", 10: "unexpected_message", 20: "bad_record_mac",
            22: "record_overflow", 40: "handshake_failure", 42: "bad_certificate",
            43: "unsupported_certificate", 46: "certificate_unknown", 47: "illegal_parameter",
            48: "unknown_ca", 49: "access_denied", 50: "decode_error",
            51: "decrypt_error", 70: "protocol_version", 71: "insufficient_security",
            80: "internal_error", 90: "user_canceled", 112: "unrecognized_name"
        }

        self.transport_dhcp = TransportDHCPManager(self.logger)
        self.transport_dhcp6 = TransportDHCP6Manager(self.logger)
        self.transport_dns = TransportDNSManager(self.logger)
        self.transport_mdns = TransportMDNSManager(self.logger)
        self.transport_nbns = TransportNBNSManager(self.logger)
        self.transport_nbds = TransportNBDSManager(self.logger)
        self.transport_ssdp = TransportSSDPManager(self.logger)
        self.transport_quic = TransportQUICManager(self.logger)
        self.transport_http = TransportHTTPManager(self.logger)
        self.transport_ssh = TransportSSHManager(self.logger)
        self.transport_ftp = TransportFTPManager(self.logger)
        self.transport_rdp = TransportRDPManager(self.logger)
        self.transport_rtp = TransportRTPManager(self.logger)
        self.transport_kerberos = TransportKerberosManager(self.logger)
        self.transport_ipv6 = TransportIPv6Manager(self.logger)
        self.transport_overlay = TransportOverlayManager(self.logger)
        self.transport_wireguard = TransportWireGuardManager(self.logger)
        self.transport_tcp_ephemeral = TransportEphemeralTCPManager(self.logger)
        self.transport_udp_ephemeral = TransportEphemeralUDPManager(self.logger)
        self.transport_steam = TransportSteamManager(self.logger)
        self.transport_tcp_high_Level = TransportHighServerTCPManager(self.logger)
        self.transport_files = TransportFileManager(self.logger)
        self.transport_https = TransportHTTPSManager(self.logger)
        self.transport_ws_discovery = TransportWSDiscoveryManager(self.logger)
        self.transport_esp = TransportESPManager(self.logger)
        self.transport_inspect = TransportInspectionManager(self.logger)
        self.transport_scraper = TransportScraperManager(self.logger)
        self.transport_llmnr = TransportLLMNRManager(self.logger)
        self.transport_undecoded = TransportUndecodedManager(self.logger)
        self.transport_stratum = TransportStratumManager(
            self.logger,
            ports={3333, 4444, 5555, 7777, 9999},
            packet_writer=self.packet_writer
        )
        self.transport_ike = TransportIkeManager(self.logger)
        self.transport_monero = TransportMoneroManager(
            self.logger,
            self.packet_writer,
        )
        self.transport_scada = TransportSCADAManager(self.logger)
        self.transport_rip = TransportRIPManager(self.logger)
        self.transport_domain = TransportDomainManager(self.logger)
        self.transport_snmp = TransportSNMPManager(self.logger)
    # ------------------------------------------------------------------
    # Safety helpers
    # ------------------------------------------------------------------

    def _freeze_packet_bytes(self, packet: Any) -> Optional[bytes]:
        try:
            if packet is None:
                return None
            if isinstance(packet, (bytes, bytearray, memoryview)):
                raw = bytes(packet)
            else:
                raw = bytes(packet)
            if not raw:
                return None
            return raw
        except Exception as e:
            self.logger.log_message(f"[Transport] ❌ failed to freeze packet: {e}")
            return None

    def _thaw_packet_bytes(self, raw_packet: bytes) -> Optional[Packet]:
        if not raw_packet:
            return None

        for parser in (Ether, IP, IPv6):
            try:
                pkt = parser(raw_packet)
                if pkt is not None:
                    return pkt
            except Exception:
                continue
        return None

    def _safe_find_transport_layer(self, packet: Packet):
        try:
            if self.sniffer and hasattr(self.sniffer, "_find_transport_layer"):
                return self.sniffer._find_transport_layer(packet)
        except Exception:
            pass

        try:
            tcp = packet.getlayer(TCP)
            if tcp is not None:
                return tcp
        except Exception:
            pass

        try:
            udp = packet.getlayer(UDP)
            if udp is not None:
                return udp
        except Exception:
            pass

        return None

    def _queue_analysis_from_raw(
        self,
        fn,
        raw_packet: bytes,
        src_ip: str,
        dst_ip: str,
        sport: int,
        dport: int,
        iface_short: str,
        queue_name: str,
    ) -> None:
        if not raw_packet:
            return

        if not self._analysis_parallel_enabled:
            try:
                fn(raw_packet, src_ip, dst_ip, sport, dport, iface_short)
            except Exception as e:
                self.logger.log_message(f"[Transport] analysis fallback error ({queue_name}): {e}")
            return

        try:
            self.parallel_python.run_parallel(
                fn,
                raw_packet,
                src_ip,
                dst_ip,
                int(sport),
                int(dport),
                iface_short,
                return_type="void",
                queue_name=queue_name,
            )
        except Exception as e:
            self.logger.log_message(
                f"[Transport] ⚠️ parallel analysis failed for {queue_name}; running local fallback: {e}"
            )
            try:
                fn(raw_packet, src_ip, dst_ip, sport, dport, iface_short)
            except Exception as inner:
                self.logger.log_message(f"[Transport] ❌ local fallback failed for {queue_name}: {inner}")

    def _inspect_from_raw(self, raw_packet: bytes, src_ip: str, dst_ip: str, sport: int, dport: int, iface_short: str):
        pkt = self._thaw_packet_bytes(raw_packet)
        if pkt is None:
            return
        try:
            self.transport_inspect.handle(pkt, src_ip, dst_ip, sport, dport, iface_short)
        except Exception as e:
            self.logger.log_message(f"[Transport] inspect error: {e}")

    def _scrape_from_raw(self, raw_packet: bytes, src_ip: str, dst_ip: str, sport: int, dport: int, iface_short: str):
        pkt = self._thaw_packet_bytes(raw_packet)
        if pkt is None:
            return
        try:
            self.transport_scraper.handle(pkt, src_ip, dst_ip, sport, dport, iface_short)
        except Exception as e:
            self.logger.log_message(f"[Transport] scrape error: {e}")

    # ------------------------------------------------------------------
    # TLS callbacks
    # ------------------------------------------------------------------

    def _on_tls_policy_decision(self, key, rec, decision):
        flow = f"{rec.src}:{rec.src_port} -> {rec.dst}:{rec.dst_port} [{rec.direction}]"
        if decision.action == "allow":
            self.logger.log_message(f"[Transport][🔐 TLS][policy] ✅ allow | {flow}")
            return

        tag_str = ",".join(decision.tags) if decision.tags else "-"
        if decision.action == "alert":
            self.logger.log_message(
                f"[Transport][🔐 TLS][policy] ⚠️ alert | {flow} | reason={decision.reason} | tags={tag_str}"
            )
            return

        self.logger.log_message(
            f"[Transport][🔐 TLS][policy] ⛔ {decision.action} | {flow} | reason={decision.reason} | tags={tag_str}"
        )
        try:
            self._enforce_tls_decision(key, rec, decision)
        except Exception as e:
            self.logger.log_message(f"[Transport][🔐 TLS][policy] enforcement error: {e}")

    def _on_tls_event(self, evt: dict):
        kind = evt.get("kind")
        data = evt.get("data", {})
        flow = evt.get("flow")

        if kind in ("client_hello", "server_hello"):
            brief = []
            if data.get("sni"):
                brief.append(f"SNI={data['sni']}")
            if data.get("ja3"):
                brief.append("ja3")
            if data.get("ja3s"):
                brief.append("ja3s")
            self.logger.log_message(f"[Transport][🔐 TLS][event] {kind} | {flow} | {' '.join(brief) or '-'}")
        elif kind in ("alert", "policy_alert", "block", "quarantine"):
            self.logger.log_message(f"[Transport][🔐 TLS][event] {kind} | {flow} | {data}")

    def _enforce_tls_decision(self, key, rec, decision):
        action = decision.action
        _ = action
        _ = decision.reason

        DROP_FUTURE_APPDATA = True
        SEND_TCP_RST = False

        if DROP_FUTURE_APPDATA:
            pass

        if SEND_TCP_RST:
            try:
                sip, sport = rec.src, rec.src_port
                dip, dport = rec.dst, rec.dst_port
                self.logger.log_message(
                    f"[Transport][🔐 TLS][policy] injected TCP RSTs for {sip}:{sport} <-> {dip}:{dport}"
                )
            except Exception as e:
                self.logger.log_message(f"[Transport][🔐 TLS][policy] RST injection failed: {e}")

    def _wire_tls_callbacks(self):
        def fmt_flow(rec: TLSRecord):
            return f"{rec.src}:{rec.src_port} -> {rec.dst}:{rec.dst_port} [{rec.direction}]"

        self.tls_manager.on_record = lambda rec: self.logger.log_message(
            f"[Transport][🔐 TLS] Record ct={rec.content_type} v={rec.version[0]}.{rec.version[1]} "
            f"len={rec.length} on {fmt_flow(rec)}"
        )

        def on_hs(rec: TLSRecord, info: Dict):
            for m in info.get("messages", []):
                t = m.get("type") or f"type={m.get('type_id')}"
                if m.get("hello") == "client":
                    v = m.get("version")
                    sni = m.get("sni") or "N/A"
                    suites = m.get("cipher_suites_count")
                    self.logger.log_message(
                        f"[Transport][🔐 TLS] ClientHello v={v} SNI={sni} suites≈{suites} on {fmt_flow(rec)}"
                    )
                elif m.get("hello") == "server":
                    v = m.get("version")
                    cs = m.get("cipher_suite")
                    self.logger.log_message(
                        f"[Transport][🔐 TLS] ServerHello v={v} cipher={cs} on {fmt_flow(rec)}"
                    )
                else:
                    self.logger.log_message(f"[Transport][🔐 TLS] Handshake {t} on {fmt_flow(rec)}")

        self.tls_manager.on_handshake = on_hs
        self.tls_manager.on_application_data = lambda rec: self.logger.log_message(
            f"[Transport][🔐 TLS] Application Data {rec.length}B on {fmt_flow(rec)}"
        )

        def on_alert(rec: TLSRecord, alert: Dict):
            lvl = self.TLS_ALERT_LEVEL.get(alert.get("level"), str(alert.get("level")))
            desc = self.TLS_ALERT_DESCRIPTION.get(alert.get("description"), str(alert.get("description")))
            self.logger.log_message(
                f"[Transport][🔐 TLS] Alert on {fmt_flow(rec)}: level={lvl} desc={desc}"
            )

        self.tls_manager.on_alert = on_alert
        self.tls_manager.on_change_cipher_spec = lambda rec: self.logger.log_message(
            f"[Transport][🔐 TLS] ChangeCipherSpec on {fmt_flow(rec)}"
        )
        self.tls_manager.on_legacy_ssl = lambda rec: self.logger.log_message(
            f"[Transport][🔐 TLS] Legacy/SSLv2-like record len={rec.length} on {fmt_flow(rec)}"
        )
        self.tls_manager.on_decision = self._on_tls_policy_decision
        self.tls_manager.on_event = self._on_tls_event

    # ------------------------------------------------------------------
    # Main packet handler (rewritten safely)
    # ------------------------------------------------------------------

    def handle_packet(self, packet: Packet, inbound_iface: str) -> bool:
        """
        Safe main transport handler.

        Differences from old behavior:
          - packet is frozen to bytes immediately
          - main TCP/UDP dispatch happens locally
          - only inspect/scrape are optionally parallelized, using bytes not Packet objects
        """
        raw_packet = self._freeze_packet_bytes(packet)
        if not raw_packet:
            return False

        iface_short = inbound_iface.split('_')[-1] if inbound_iface else "unknown"

        local_packet = self._thaw_packet_bytes(raw_packet)
        if local_packet is None:
            self.logger.log_message("[Transport] ❌ unable to parse frozen packet")
            return False

        ip_layer = local_packet.getlayer(IP) or local_packet.getlayer(IPv6)
        if not ip_layer:
            return False

        src_ip = ip_layer.src
        dst_ip = ip_layer.dst

        transport_layer = self._safe_find_transport_layer(local_packet)
        if isinstance(transport_layer, TCP):
            sport = int(transport_layer.sport)
            dport = int(transport_layer.dport)

            self._queue_analysis_from_raw(
                self._inspect_from_raw,
                raw_packet,
                src_ip,
                dst_ip,
                sport,
                dport,
                iface_short,
                queue_name="transport_inspect_tcp_packets",
            )
            self._queue_analysis_from_raw(
                self._scrape_from_raw,
                raw_packet,
                src_ip,
                dst_ip,
                sport,
                dport,
                iface_short,
                queue_name="transport_scrape_tcp_packets",
            )

            with self._dispatch_lock:
                return bool(self._handle_tcp_packet(local_packet, src_ip, dst_ip, sport, dport, iface_short))

        if isinstance(transport_layer, UDP):
            sport = int(transport_layer.sport)
            dport = int(transport_layer.dport)

            self._queue_analysis_from_raw(
                self._inspect_from_raw,
                raw_packet,
                src_ip,
                dst_ip,
                sport,
                dport,
                iface_short,
                queue_name="transport_inspect_udp_packets",
            )
            self._queue_analysis_from_raw(
                self._scrape_from_raw,
                raw_packet,
                src_ip,
                dst_ip,
                sport,
                dport,
                iface_short,
                queue_name="transport_scrape_udp_packets",
            )

            with self._dispatch_lock:
                return bool(self._handle_udp_packet(local_packet, src_ip, dst_ip, sport, dport, iface_short))

        try:
            self.transport_ipv6.handle(local_packet, inbound_iface)
        except Exception as e:
            self.logger.log_message(f"[Transport] IPv6 handler error: {e}")
        return False

    # ------------------------------------------------------------------
    # Existing methods below can stay mostly the same
    # ------------------------------------------------------------------

    def _canonical_flow_key(self, a_ip, a_port, b_ip, b_port):
        t1 = (a_ip, a_port)
        t2 = (b_ip, b_port)
        return (t1, t2) if t1 <= t2 else (t2, t1)

    def _handle_tcp_packet(self, packet, src_ip, dst_ip, sport, dport, iface_short):
        tcp = packet[TCP]
        flags = tcp.sprintf("%TCP.flags%")

        if "S" in flags and "A" not in flags:
            key = self._canonical_flow_key(src_ip, sport, dst_ip, dport)
            self._initiators[key] = (src_ip, int(sport))

        rules = [
            ([502, 2404, 102, 4840, 20000], self._handle_scada_tcp_packet),
            ([80], self._handle_http_packet),
            ([3333, 4444, 5555, 7777, 9999], self._handle_stratum_packet),
            ([443, 8443, 9443, 2087, 2096, 2083], self._handle_https_packet),
            ([53], self._handle_domain_tcp_packet),
            ([22], self._handle_ssh_packet),
            ([21], self._handle_ftp_packet),
            ([88], self._handle_kerberos_packet),
            ([3389], self._handle_rdp_packet),
            ([18080, 28080, 38080, 41257, 18081, 18083, 18089, 28081, 38081, 37888, 37889], self._handle_monero_packet),
            ([(27014, 27050)], self._handle_tcp_steam_packet),
            ([(33981, 59713), (60000, 61000)], self._handle_tcp_ephemeral_packet),
            ([(1024, 65535)], self._handle_high_server_packet),
            ([445, 139, 62078], self._handle_files_packet),
            ([161, 162, 10161, 10162], self._handle_snmp_tcp_packet),
        ]

        handler = None
        for ports, h in rules:
            for p in ports:
                if isinstance(p, tuple):
                    lo, hi = p
                    if lo <= sport <= hi or lo <= dport <= hi:
                        handler = h
                        break
                else:
                    if p in (sport, dport):
                        handler = h
                        break
            if handler:
                break
        if self.packet_writer.should_drop_packet(packet, inbound_iface=iface_short, consume=True):
            return False
        if handler:
            if handler == self._handle_tcp_ephemeral_packet:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                return False
            else:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                self.packet_writer._send_raw_packet(packet, iface_short, allow_dst_ours=True, no_consume=True)
            return True

        return False

    def _handle_udp_packet(self, packet, src_ip, dst_ip, sport, dport, iface_short):
        if sport == 500 or dport == 500:
            return False

        rules = [
            ([520, 521], self._handle_rip_packet),
            ([53], self._handle_dns_packet),
            ([5353], self._handle_mdns_packet),
            ([5355], self._handle_llmnr_packet),
            ([137], self._handle_nbns_packet),
            ([138], self._handle_nbds_packet),
            ([67, 68], self._handle_dhcp_packet),
            ([500, 4500], self._handle_esp_packet),
            ([546, 547], self._handle_dhcp6_packet),
            ([51820, 88, 59385, 59636, 59637, 59638, 61138], self._handle_wireguard_packet),
            ([443], self._handle_quic_packet),
            ([123], self._handle_ntp_packet),
            ([69], self._handle_tftp_packet),
            ([88], self._handle_kerberos_packet),
            ([5060], self._handle_sip_packet),
            ([9993, 19300], self._handle_overlay_packet),
            ([1900], self._handle_ssdp_packet),
            ([3702], self._handle_ws_discovery_packet),
            ([19337, 19307], self._handle_rtp_packet),
            ([20000, 47808], self._handle_scada_udp_packet),
            ([(27000, 27100), 4380, 27036, 27037], self._handle_udp_steam_packet),
            ([(49152, 65535), 3478, 5349], self._handle_udp_ephemeral_packet),
            ([161, 162, 10161, 10162], self._handle_snmp_udp_packet),
        ]

        def _match(ports_or_ranges, s, d):
            for p in ports_or_ranges:
                if isinstance(p, tuple):
                    lo, hi = p
                    if lo <= s <= hi or lo <= d <= hi:
                        return True
                else:
                    if p == s or p == d:
                        return True
            return False

        handler = None
        for ports, h in rules:
            if _match(ports, sport, dport):
                handler = h
                break
        if self.packet_writer.should_drop_packet(packet, inbound_iface=iface_short, consume=True):
            return False
        if handler:
            if handler == self._handle_dhcp_packet:
                return handler(packet, src_ip, dst_ip, sport, dport, iface_short)
            elif handler == self._handle_dhcp6_packet:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                return False
            elif handler == self._handle_kerberos_packet:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                return False
            elif handler == self._handle_dns_packet:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                return False
            elif handler == self._handle_mdns_packet:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                return False
            elif handler == self._handle_ws_discovery_packet:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                self.packet_writer._send_raw_packet(packet, iface_short, allow_dst_ours=True, no_consume=False)
                return True
            elif handler == self._handle_ssdp_packet:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                self.packet_writer._send_raw_packet(packet, iface_short, allow_dst_ours=True, no_consume=False)
                return True
            elif handler == self._handle_udp_ephemeral_packet:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                return False
            else:
                handler(packet, src_ip, dst_ip, sport, dport, iface_short)
                self.packet_writer._send_raw_packet(packet, iface_short, allow_dst_ours=True, no_consume=True)
                return True

        try:
            if sport in self.voip_port_range or dport in self.voip_port_range:
                self._handle_rtp_packet(packet, src_ip, dst_ip, sport, dport, iface_short)
                return True
        except Exception:
            pass

        self.code_output_manager.submit_packet(
            packet, inbound_iface=iface_short, phase="unhandled", component="udp"
        )
        self.transport_undecoded.handle(packet, src_ip, dst_ip, sport, dport, iface_short)
        self.packet_writer._send_raw_packet(packet, iface_short, allow_dst_ours=True, no_consume=False)
        return True


